(window.JCPA_DATA=window.JCPA_DATA||{})["investment"]={"id":"investment","name":"قانون الاستثمار","full":"قانون البيئة الاستثمارية رقم (21) لسنة 2022","icon":"📈","articles":[{"n":"1","chapter":"","notes":[],"source":"يسمى هذا القانون (قانون البيئة الاستثمارية لسنة٢٠٢٢) ويعمل به بعد تسعين يوماً من تاريخ نشره في الجريدة الرسمية.","title":"اسم القانون وبدء العمل به","memo":"⭐ قانون البيئة الاستثمارية لسنة ٢٠٢٢\n⭐ يعمل به بعد (٩٠) يوماً من تاريخ نشره في الجريدة الرسمية","qs":[{"q":"يعمل بقانون البيئة الاستثمارية لسنة ٢٠٢٢:","o":["بعد تسعين يوماً من تاريخ نشره في الجريدة الرسمية","من تاريخ نشره في الجريدة الرسمية","بعد ثلاثين يوماً من تاريخ نشره في الجريدة الرسمية","بعد ستة أشهر من تاريخ نشره في الجريدة الرسمية"],"a":0}]},{"n":"2","chapter":"","notes":[],"source":"يكون للكلمات والعبارات التالية حيثما وردت في هذا القانون المعاني المخصصة لها أدناه مالم تدل القرينة على غير ذلك:-\nالوزارة : وزارة الاستثمار.\nالوزير : وزير الاستثمار.\nالمجلس : مجلس الاستثمار المشكل بمقتضى احكام هذا القانون.\nالاستثمار : إنشاء نشاط اقتصادي في المملكة بما في ذلك التملك أو المشاركة أو التطوير أو التوسعة.\nالنشاط الاقتصادي : أي نشاط صناعي أو تجاري أو زراعي او خدمي أو سياحي أو تكنولوجيا معلومات أو صناعة إبداعية ولا يشمل المصرفية أو الصيرفة أو النشاطات المهنية المنظمة بموجب تشريعات خاصة.\nالشخص : الشخص الطبيعي أو الاعتباري.\nالمستثمر : الشخص الذي يستثمر في المملكة في نشاط اقتصادي وفق أحكام القانون، سواء كان مستثمرا أردنياً أو غير أردني.\nالرخصة : التصريح أو الموافقة أو الإذن أو الترخيص الصادر عن الجهة الرسمية لأي شخص للسماح له بمزاولة نشاط اقتصادي معين.\nالجهة الرسمية : أي وزارة أو دائرة أو هيئة أو مجلس أو أمانة عمان أو بلدية أو سلطة أو مؤسسة رسمية عامة.\nالأصول : الأموال المنقولة وغير المنقولة سواء أكانت مادية أو معنوية المستثمرة في النشاط الاقتصادي.\nلجنة الحوافز والإعفاءات : اللجنة الوزارية للحوافز والإعفاءات المشكلة بمقتضى أحكام المادة (١٢) من هذا القانون.\nلجنة التظلمات : اللجنة المشكلة بقرار من الوزير بمقتضى أحكام المادة (٤٤) من هذا القانون.\nالمنطقة : المنطقة التنموية والمنطقة الحرة.\nالمنطقة التنموية : أي منطقة تقع ضمن النطاق الجمركي للمملكة يتم اعلانها منطقة تنموية وفقا لأحكام هذا القانون\nالمنطقة الحرة : جزء من أراضي المملكة محدد ومسور بحاجز فاصل يخصص لغايات ممارسة الانشطة الاقتصادية بما فيها تخزين السلع ويعتبر خارج النطاق الجمركي وتعامل السلع والانشطة الاقتصادية داخله على انها خارج المملكة لغايات تطبيق احكام هذا القانون.\nالمطور الرئيسي : الشخص الاعتباري الذي يتولى ادارة المنطقة وتطويرها بموجب اتفاقية التطوير وأحكام هذا القانون.\nالمؤسسة المسجلة : الشخص الذي يتم تسجيله لدى الوزارة لممارسة النشاط الاقتصادي في المنطقة وفقا لأحكام هذا القانون.\nاتفاقية التطوير : اتفاقية تبرم بين الوزارة والمطور الرئيسي لإدارة المنطقة وتطويرها وفقا لأحكام هذا القانون والأنظمة الصادرة بمقتضاه.\nالخدمة الاستثمارية الشاملة : الخدمات المقدمة للأنشطة الاقتصادية من الجهة الرسمية بما في ذلك خدمات التسجيل والترخيص من موقع واحد متضمنا المنصات الالكترونية.\nصندوق الاستثمار : الصندوق الذي يتم انشاؤه وفقاً لأحكام هذا القانون والنظام الصادر بمقتضاه .\nصندوق الاستثمار المشترك : الصندوق المنشأ وفقاً لأحكام قانون الأوراق المالية.","title":"التعريفات","memo":"⭐ النشاط الاقتصادي: صناعي/تجاري/زراعي/خدمي/سياحي/تكنولوجيا معلومات/صناعة إبداعية — ولا يشمل المصرفية أو الصيرفة أو النشاطات المهنية المنظمة بتشريعات خاصة\n⭐ المنطقة = التنموية + الحرة؛ التنموية ضمن النطاق الجمركي، والحرة خارج النطاق الجمركي ومسورة بحاجز فاصل\n⭐ المطور الرئيسي: شخص اعتباري يدير المنطقة ويطورها بموجب اتفاقية التطوير المبرمة مع الوزارة\n⭐ لجنة الحوافز والإعفاءات: لجنة وزارية (م١٢)؛ لجنة التظلمات: بقرار من الوزير (م٤٤)","qs":[{"q":"أي مما يلي لا يندرج ضمن تعريف (النشاط الاقتصادي) وفق قانون البيئة الاستثمارية؟","o":["النشاط المصرفي","النشاط السياحي","الصناعة الإبداعية","نشاط تكنولوجيا المعلومات"],"a":0},{"q":"وفقاً للتعريفات، تعتبر المنطقة الحرة:","o":["خارج النطاق الجمركي وتعامل السلع داخلها على أنها خارج المملكة","ضمن النطاق الجمركي للمملكة","جزءاً من المنطقة التنموية حكماً","منطقة غير مسورة تخضع للرسوم الجمركية"],"a":0},{"q":"المطور الرئيسي هو:","o":["الشخص الاعتباري الذي يتولى إدارة المنطقة وتطويرها بموجب اتفاقية التطوير","الشخص الطبيعي أو الاعتباري المسجل لدى الوزارة لممارسة النشاط في المنطقة","الجهة الرسمية التي تشرف على المناطق التنموية","أي مستثمر يمتلك أرضاً داخل المنطقة"],"a":0},{"q":"تبرم اتفاقية التطوير بين:","o":["الوزارة والمطور الرئيسي","المطور الرئيسي والمؤسسة المسجلة","مجلس الوزراء والمستثمر","المجلس والمطور الرئيسي"],"a":0}]},{"n":"3","chapter":"الفصل الأول - السياسة العامة للاستثمار وحقوق المستثمرين","notes":[],"source":"تقوم السياسة العامة للاستثمار في المملكة على تحقيق رؤى اقتصادية وتنموية تهدف الى توفير فرص العمل وزيادة النمو الاقتصادي وتحسين التنافسية وبيئة الاعمال وترتكز على المبادئ التالية:-\nأ- المساواة بين المستثمر الأردني وغير الأردني في الحقوق والامتيازات والواجبات، ومعاملة جميع المستثمرين معاملة عادلة ومنصفة وشفافة.\nب- حماية الاستثمارات وعدم التدخل في الأنشطة والحقوق والمصالح المعترف بها قانونا للمستثمر أو الشركة التي تم الاستثمار بها.\nج- التحول من مبادئ الرقابة المسبقة الى الرقابة اللاحقة، وفقا لمتطلبات ممارسة الأعمال المعلن عنها مسبقا.\nد- تحفيز وتشجيع الاستثمار في المشاريع الريادية والابتكار ومشاريع البحث والتطوير.\nهـ- تهيئة البيئة المناسبة لتنمية المشاريع الصغيرة والمتوسطة.\nو- رقمنة وأتمتة كافة الإجراءات والخدمات المقدمة للمستثمرين.\nز- تعزيز المنافسة ومنع الاحتكار وضمان حماية المستهلك.\nح- حماية البيئة والتحول الى الاقتصاد الاخضر والسلامة والصحة العامة ومراعاة المعايير الاجتماعية .","title":"مبادئ السياسة العامة للاستثمار","memo":"⭐ تهدف إلى توفير فرص العمل وزيادة النمو الاقتصادي وتحسين التنافسية وبيئة الأعمال\n⭐ المساواة بين المستثمر الأردني وغير الأردني في الحقوق والامتيازات والواجبات\n⭐ التحول من الرقابة المسبقة إلى الرقابة اللاحقة\n⭐ رقمنة وأتمتة الإجراءات، ومنع الاحتكار، وحماية البيئة والتحول للاقتصاد الأخضر","qs":[{"q":"من المبادئ التي ترتكز عليها السياسة العامة للاستثمار:","o":["التحول من مبادئ الرقابة المسبقة إلى الرقابة اللاحقة","التحول من الرقابة اللاحقة إلى الرقابة المسبقة","تفضيل المستثمر الأردني على غير الأردني في الامتيازات","حصر الاستثمار في المشاريع الكبرى دون الصغيرة والمتوسطة"],"a":0},{"q":"أي مما يلي ليس من المبادئ التي ترتكز عليها السياسة العامة للاستثمار؟","o":["منح المستثمر الأردني امتيازات تفوق المستثمر غير الأردني","تعزيز المنافسة ومنع الاحتكار وضمان حماية المستهلك","رقمنة وأتمتة كافة الإجراءات والخدمات المقدمة للمستثمرين","تهيئة البيئة المناسبة لتنمية المشاريع الصغيرة والمتوسطة"],"a":0},{"q":"تقوم معاملة المستثمرين وفق السياسة العامة للاستثمار على أساس:","o":["المساواة بين المستثمر الأردني وغير الأردني ومعاملة عادلة ومنصفة وشفافة","المعاملة بالمثل مع دولة المستثمر","حجم رأس المال المستثمر","جنسية المستثمر"],"a":0}]},{"n":"4","chapter":"الفصل الأول - السياسة العامة للاستثمار وحقوق المستثمرين","notes":[],"source":"أ- يجوز إنشاء صناديق استثمار لرصد الأموال لغايات استثمارها في الأنشطة الاقتصادية ويكتسب صندوق الاستثمار بعد إنشائه وتسجيله الشخصية الاعتبارية.\nب- تحدد شروط انشاء صناديق الاستثمار وتسجيلها والجهات التي يجوز لها انشاؤها وسائر الأحكام المتعلقة بها بمقتضى نظام.","title":"صناديق الاستثمار","memo":"⭐ يجوز إنشاء صناديق استثمار لرصد الأموال لاستثمارها في الأنشطة الاقتصادية\n⭐ يكتسب الصندوق الشخصية الاعتبارية بعد إنشائه وتسجيله\n⭐ شروط الإنشاء والتسجيل والجهات التي يجوز لها إنشاؤها تحدد بمقتضى نظام","qs":[{"q":"يكتسب صندوق الاستثمار الشخصية الاعتبارية:","o":["بعد إنشائه وتسجيله","بمجرد صدور قرار إنشائه","بعد موافقة مجلس الاستثمار عليه","بعد مباشرة أول استثمار له"],"a":0},{"q":"تحدد شروط إنشاء صناديق الاستثمار والجهات التي يجوز لها إنشاؤها بمقتضى:","o":["نظام","تعليمات يصدرها الوزير","قرار من مجلس الاستثمار","قرار من لجنة الحوافز والإعفاءات"],"a":0}]},{"n":"5","chapter":"الفصل الأول - السياسة العامة للاستثمار وحقوق المستثمرين","notes":[],"source":"يحق للمستثمر ما يلي:-\nأ- الاستثمار في المملكة بالتملك الكامل أو المشاركة أو المساهمة في أي نشاط اقتصادي، باستثناء الأنشطة الاقتصادية المقيدة بمقتضى نظام.\nب- تحويل العملة المستخدمة في المملكة بصورة قانونية الى عملة قابلة للتحويل.\nج- تحويل العملات القابلة للتحويل داخل المملكة وخارجها دون تأخير ووفقاً للممارسات المالية العالمية والتشريعات النافذة.\nد- المطالبة بالتعويض عن الخسائر المتحققة على اعتماد المستثمر بحسن نية على أي قرار صادر عن الجهة الرسمية تجاهه، أو أي التزام اخذته تلك الجهة على عاتقها تجاه المستثمر، وكان إصدار مثل هذا القرار أو الاخذ بهذا الالتزام خارج اختصاصها على ان يتم التعويض وفقاً لأحكام الفقرة (ب) من المادة (٦) من هذا القانون.\nهـ- استخدام غير الأردنيين في الوظائف الإدارية والفنية التي تتطلب مهارات متخصصة بنسبة لا تزيد على (٢٥%) من اجمالي عدد العاملين ويجوز رفع هذه النسبة الى مالا يزيد على نسبة (٤٠%) في حال عدم إمكانية توفير عمالة أردنية لهذه الوظائف.\nو- تصفية أو إنهاء الأنشطة الاستثمارية الخاصة به.\nز- أي حقوق أخرى يمنحها له هذا القانون والتشريعات النافذة.","title":"حقوق المستثمر","memo":"⭐ التملك الكامل أو المشاركة في أي نشاط اقتصادي باستثناء الأنشطة المقيدة بمقتضى نظام\n⭐ تحويل العملات دون تأخير، والمطالبة بالتعويض عن الاعتماد بحسن نية على قرار خارج اختصاص الجهة الرسمية\n⭐ استخدام غير الأردنيين في الوظائف المتخصصة بنسبة لا تزيد على (٢٥%) ويجوز رفعها إلى (٤٠%) عند عدم توفر عمالة أردنية\n⭐ تصفية أو إنهاء أنشطته الاستثمارية","qs":[{"q":"الحد الأعلى الأصلي لنسبة استخدام غير الأردنيين في الوظائف الإدارية والفنية المتخصصة من إجمالي عدد العاملين:","o":["٢٥%","٤٠%","٣٠%","٥٠%"],"a":0},{"q":"شركة استثمارية لم تتمكن من توفير عمالة أردنية لوظائف فنية متخصصة، فإن أقصى نسبة يجوز رفع استخدام غير الأردنيين إليها هي:","o":["٤٠%","٢٥%","٥٠%","٣٥%"],"a":0},{"q":"يحق للمستثمر التملك الكامل في أي نشاط اقتصادي باستثناء:","o":["الأنشطة الاقتصادية المقيدة بمقتضى نظام","الأنشطة الصناعية","الأنشطة السياحية","الأنشطة الواقعة في المناطق الأقل نمواً"],"a":0},{"q":"يتم تعويض المستثمر عن الخسائر الناتجة عن اعتماده بحسن نية على قرار صادر عن جهة رسمية خارج اختصاصها:","o":["وفقاً لأحكام الفقرة (ب) من المادة (٦) من القانون","وفقاً لما تقرره لجنة التظلمات","وفقاً لما يقرره مجلس الاستثمار","بنسبة (٥٠%) من الخسائر المتحققة"],"a":0}]},{"n":"6","chapter":"الفصل الأول - السياسة العامة للاستثمار وحقوق المستثمرين","notes":[],"source":"أ-لا يجوز نزع ملكية أي استثمار أو جزء منه إلا بمقتضى القانون ولغرض عام ومحدد ومشروع وبطريقة غير تمييزية مقابل دفع تعويض عادل للمستثمر.\nب- يراعى عند دفع التعويض المشار إليه في الفقرة (أ) من هذه المادة ما يلي:-\n١- أن يدفع دفعة واحدة بالدينار الأردني أو بعملة قابلة للتحويل.\n٢- أن يكون مساوياً للقيمة السوقية العادلة للأصول المعنية قبل اتخاذ قرار نزع الملكية.\n٣- أن يشمل سعر فائدة يعادل التمويل المضمون لليلة واحدة الذي ينشره يومياً البنك المركزي الأردني.","title":"نزع ملكية الاستثمار والتعويض","memo":"⭐ لا نزع ملكية إلا بمقتضى القانون ولغرض عام ومحدد ومشروع وبطريقة غير تمييزية مقابل تعويض عادل\n⭐ يدفع التعويض دفعة واحدة بالدينار الأردني أو بعملة قابلة للتحويل\n⭐ يساوي القيمة السوقية العادلة للأصول قبل اتخاذ قرار نزع الملكية\n⭐ يشمل فائدة تعادل التمويل المضمون لليلة واحدة الذي ينشره البنك المركزي يومياً","qs":[{"q":"يدفع التعويض عن نزع ملكية الاستثمار:","o":["دفعة واحدة بالدينار الأردني أو بعملة قابلة للتحويل","على أقساط سنوية بالدينار الأردني فقط","دفعة واحدة بعملة دولة المستثمر حصراً","على دفعتين خلال سنة من قرار نزع الملكية"],"a":0},{"q":"يكون التعويض عن نزع الملكية مساوياً لـ:","o":["القيمة السوقية العادلة للأصول المعنية قبل اتخاذ قرار نزع الملكية","القيمة الدفترية للأصول في آخر بيانات مالية","القيمة السوقية للأصول بعد اتخاذ قرار نزع الملكية","تكلفة شراء الأصول التاريخية"],"a":0},{"q":"سعر الفائدة الذي يشمله التعويض عن نزع الملكية يعادل:","o":["التمويل المضمون لليلة واحدة الذي ينشره البنك المركزي الأردني يومياً","سعر إعادة الخصم لدى البنك المركزي","متوسط أسعار الفائدة على الودائع لدى البنوك","سعر الفائدة القانونية المحدد في القانون المدني"],"a":0}]},{"n":"7","chapter":"الفصل الثاني - وزارة الاستثمار ومجلس الاستثمار","notes":[],"source":"أ- تعتبر الوزارة المرجعية الرئيسة للاستثمار في المملكة، وتهدف الى جذب الاستثمار وتشجيعه وترويجه وضمان ديمومة المناخ الاستثماري الجاذب وتعزيز الثقة في البيئة الاستثمارية وتنميتها وتنظيمها.\nب- تتولى الوزارة في سبيل تحقيق أهدافها المهام والصلاحيات التالية:- ١-تنفيذ السياسة الاستثمارية للمملكة ووضع الخطط الاستراتيجية والبرامج اللازمة لتحفيز الاستثمارات المحلية والاجنبية بما فيها صناديق الاستثمار وصناديق الاستثمار المشترك.\n٢-إعداد مشروع الخارطة الاستثمارية للمملكة التي تحدد الفرص الاستثمارية المتاحة حسب القطاعات والمحافظات بما فيها مشاريع الشراكة مع القطاع الخاص بالتنسيق والتعاون مع الجهات المعنية على أن يتم التحديث بشكل مستمر.\n٣-ترويج الفرص الاستثمارية المتاحة في المملكة وتوفير المعلومات والبيانات للمستثمرين والراغبين في الاستثمار والترويج للمشاريع الاقتصادية والاستثمارية الكبرى ومتابعة تقدم سير العمل في تنفيذها.\n٤-تقديم الخدمات الداعمة للمستثمرين، بما فيها خدمات ما بعد بدء الاستثمار.\n٥-تسهيل الاجراءات وتذليل الصعوبات وإزالة المعوقات أمام المستثمرين للبدء في ممارسة نشاطهم الاقتصادي واستمراره.\n٦- إصدار وتحديث الأدلة الارشادية للاستثمار وممارسة الاعمال في المملكة.\n٧-إعداد الدراسات القطاعية ودراسات الجدوى الأولية للفرص الاستثمارية المتاحة، وبناء قاعدة بيانات حولها.\n٨- الإشراف على المناطق التنموية والحرة وتنظيم عملها.\n٩-متابعة تصنيف المملكة وترتيبها في التقارير والمؤشرات الدولية الخاصة بالاستثمار، والعمل على وضع وتنفيذ الخطط اللازمة لتعزيز تنافسية المملكة استثماريا.\n١٠-النظر في طلبات التظلم المقدمة من المستثمرين للتحقق من سلامة الإجراءات المتخذة أو القرارات الصادرة عن الجهة الرسمية والعمل على معالجتها وفقا للتشريعات النافذة.\n١١- إعداد التقارير المتعلقة بتنفيذ الخطط والاستراتيجيات والبرامج المتعلقة بالاستثمار.\n١٢- الاشراف على عمل وحدة الشراكة بين القطاعين العام والخاص.","title":"أهداف الوزارة ومهامها","memo":"⭐ الوزارة هي المرجعية الرئيسة للاستثمار في المملكة\n⭐ تعد مشروع الخارطة الاستثمارية (حسب القطاعات والمحافظات) وتحدّثها باستمرار — ويقرّها المجلس (م٨)\n⭐ تشرف على المناطق التنموية والحرة وعلى وحدة الشراكة بين القطاعين العام والخاص\n⭐ تنظر في طلبات التظلم المقدمة من المستثمرين","qs":[{"q":"المرجعية الرئيسة للاستثمار في المملكة هي:","o":["وزارة الاستثمار","مجلس الاستثمار","وزارة الصناعة والتجارة والتموين","لجنة الحوافز والإعفاءات"],"a":0},{"q":"الجهة التي تتولى إعداد مشروع الخارطة الاستثمارية للمملكة:","o":["وزارة الاستثمار","مجلس الوزراء","وزارة التخطيط والتعاون الدولي","المطور الرئيسي"],"a":0},{"q":"أي مما يلي ليس من مهام وزارة الاستثمار وفق المادة (٧)؟","o":["إقرار السياسة الاستثمارية للمملكة","الإشراف على المناطق التنموية والحرة وتنظيم عملها","الإشراف على عمل وحدة الشراكة بين القطاعين العام والخاص","إصدار وتحديث الأدلة الإرشادية للاستثمار"],"a":0}]},{"n":"8","chapter":"الفصل الثاني - وزارة الاستثمار ومجلس الاستثمار","notes":[],"source":"أ- يشكل مجلس يسمى (مجلس الاستثمار) برئاسة رئيس الوزراء وعضوية كل من:-\n١- وزير الاستثمار نائباً للرئيس.\n٢- وزير التخطيط والتعاون الدولي.\n٣- وزير المالية.\n٤- وزير الصناعة والتجارة والتموين.\n٥- وزير الاقتصاد الرقمي والريادة .\n٦- محافظ البنك المركزي الأردني.\n٧- رئيس مجلس إدارة غرفة تجارة الأردن .\n٨- رئيس مجلس إدارة غرفة صناعة الأردن.\n٩- أربعة ممثلين عن القطاع الخاص على ان يكون من بينهم سيدة أعمال وثلاثة ممثلين عن القطاع الزراعي والسياحي والخدمات المالية.\nب- تتم تسمية الأعضاء المشار إليهم في البند (٩) من الفقرة (أ) من هذه المادة بقرار من مجلس الوزراء بناء على تنسيب رئيس الوزراء لمدة سنتين قابلة للتجديد لمرة واحدة ويجوز إنهاء عضوية أي منهم بتعيين بديل له للمدة المتبقية من عضويته بالطريقة ذاتها.\nج- يتولى المجلس المهام والصلاحيات التالية:-\n١- إقرار السياسة الاستثمارية التي تتضمن القطاعات والمشاريع ذات الأولوية المستهدفة، بما يتفق مع السياسة العامة للدولة والرؤية الاقتصادية والخطط والبرامج التنفيذية الاقتصادية والاجتماعية. ٢- إقرار الخارطة الاستثمارية للمملكة ومتابعة تحديثها.\n٣- مناقشة التقارير المتعلقة بتنفيذ الخطط والاستراتيجيات والبرامج المتعلقة بالاستثمار والتوجيه بشأنها.\n٤- التوجيه باتخاذ كل ما يلزم لتطوير البيئة الاستثمارية للمملكة.\n٥- التوصية بالتعديلات التشريعية والتنظيمية اللازمة لتحسين بيئة الاستثمار.\n٦- البت في الخلافات التي قد تنشأ بين الجهات الرسمية فيما يتعلق بالبيئة الاستثمارية.\n٧- أي أمور أخرى تتعلق بالاستثمار باستثناء ما هو من صلاحيات الوزارة.\nد- يجتمع المجلس بدعوة من رئيسه مرة على الأقل كل ثلاثة أشهر ويكون اجتماعه قانونياً بحضور ما لا يقل عن أغلبية أعضائه ويتخذ قراراته بأغلبية أصوات أعضائه.\nهـ- للمجلس دعوة من يراه مناسبا من الخبراء والمختصين للمشاركة في اجتماعاته للاستئناس برأيه دون ان يكون له حق التصويت على قرارات المجلس.\nو- يكون أمين عام الوزارة أمين سر للمجلس.\nز- تنظم الأحكام والإجراءات المتعلقة بعمل المجلس بمقتضى تعليمات يصدرها لهذه الغاية.","title":"مجلس الاستثمار","memo":"⭐ برئاسة رئيس الوزراء، ووزير الاستثمار نائباً للرئيس، ومن أعضائه محافظ البنك المركزي ورئيسا غرفتي تجارة وصناعة الأردن\n⭐ (٤) ممثلين عن القطاع الخاص بينهم سيدة أعمال، يسميهم مجلس الوزراء بتنسيب رئيس الوزراء لمدة سنتين قابلة للتجديد مرة واحدة\n⭐ يجتمع مرة على الأقل كل (٣) أشهر، النصاب أغلبية الأعضاء، والقرارات بأغلبية أصوات الأعضاء\n⭐ أمين عام الوزارة أمين سر المجلس؛ ويقر السياسة الاستثمارية والخارطة الاستثمارية ويبت في خلافات الجهات الرسمية","qs":[{"q":"يرأس مجلس الاستثمار:","o":["رئيس الوزراء","وزير الاستثمار","وزير المالية","محافظ البنك المركزي الأردني"],"a":0},{"q":"مدة عضوية ممثلي القطاع الخاص في مجلس الاستثمار:","o":["سنتان قابلة للتجديد لمرة واحدة","ثلاث سنوات قابلة للتجديد","أربع سنوات غير قابلة للتجديد","سنة واحدة قابلة للتجديد"],"a":0},{"q":"يجتمع مجلس الاستثمار بدعوة من رئيسه مرة على الأقل كل:","o":["ثلاثة أشهر","شهر","ستة أشهر","سنة"],"a":0},{"q":"أي مما يلي ليس من صلاحيات مجلس الاستثمار؟","o":["الإشراف على المناطق التنموية والحرة وتنظيم عملها","إقرار الخارطة الاستثمارية للمملكة ومتابعة تحديثها","البت في الخلافات بين الجهات الرسمية فيما يتعلق بالبيئة الاستثمارية","التوصية بالتعديلات التشريعية اللازمة لتحسين بيئة الاستثمار"],"a":0}]},{"n":"9","chapter":"أولاً:- الحوافز الأساسية","notes":[],"source":"أ- على الرغم مما ورد في قانون الجمارك، تعفى الموجودات الثابتة ومستلزمات ومدخلات الإنتاج وقطع الغيار للنشاط الاقتصادي من الرسوم الجمركية.\nب-١- يصدر مجلس الوزراء بناء على تنسيب لجنة الحوافز والإعفاءات جدولاً يتضمن الموجودات الثابتة ومستلزمات ومدخلات الإنتاج وقطع الغيار اللازمة لممارسة النشاط الاقتصادي الخاضعة للضريبة بنسبة الصفر .\n٢- لمجلس الوزراء بناء على تنسيب مبرر من لجنة الحوافز والإعفاءات تعديل الجدول المشار إليه في البند (١) من هذه الفقرة.","title":"الإعفاء الجمركي ومدخلات الإنتاج","memo":"⭐ على الرغم من قانون الجمارك: تعفى الموجودات الثابتة ومستلزمات ومدخلات الإنتاج وقطع الغيار من الرسوم الجمركية\n⭐ يصدر مجلس الوزراء بتنسيب لجنة الحوافز والإعفاءات جدولاً بالسلع الخاضعة للضريبة بنسبة الصفر\n⭐ تعديل الجدول: مجلس الوزراء بتنسيب مبرر من لجنة الحوافز والإعفاءات","qs":[{"q":"تعفى الموجودات الثابتة ومستلزمات ومدخلات الإنتاج وقطع الغيار للنشاط الاقتصادي من:","o":["الرسوم الجمركية","ضريبة الدخل","ضريبة الأبنية والأراضي","رسوم الترخيص"],"a":0},{"q":"الجهة التي تصدر جدول الموجودات الثابتة ومدخلات الإنتاج الخاضعة للضريبة بنسبة الصفر:","o":["مجلس الوزراء بناء على تنسيب لجنة الحوافز والإعفاءات","الوزير بناء على تنسيب مجلس الاستثمار","لجنة الحوافز والإعفاءات منفردة","وزير المالية بناء على تنسيب مدير عام الجمارك"],"a":0},{"q":"تخضع الموجودات الثابتة ومستلزمات الإنتاج الواردة في الجدول الصادر بمقتضى المادة (٩) للضريبة بنسبة:","o":["الصفر","٧%","١٦%","٥%"],"a":0}]},{"n":"10","chapter":"الفصل الثالث - الحوافز الممنوحة خارج المناطق التنموية والمناطق الحرة","notes":[],"source":"على الرغم مما ورد في قانون ضريبة الدخل، يتم الإعفاء من ضريبة الدخل المستحقة أو تخفيضها بنسبة لا تقل عن (٣٠%) على الأنشطة الاقتصادية في المناطق الأقل نمواً في المملكة أو المشاريع التي تشغل (٢٥٠) أردنيا على الأقل، ولمدة (٥) سنوات من تاريخ التشغيل الفعلي حدا أعلى، وتحدد الأحكام المتعلقة بذلك بمقتضى نظام يتضمن ما يلي:-\nأ- الأنشطة الاقتصادية التي تتمتع بالإعفاء من ضريبة الدخل.\nب- الانشطة الاقتصادية التي تتمتع بالتخفيض من ضريبة الدخل ونسب التخفيض لكل منها .\nج- أسس ومعايير وشروط ومدد التمتع بالإعفاء أو التخفيض من ضريبة الدخل .\nد- الأنشطة الاقتصادية المستثناة من الإعفاء أو التخفيض من ضريبة الدخل.\nهـ- تحديد المناطق الأقل نموا في المملكة لغايات التمتع بالإعفاء أو التخفيض من ضريبة الدخل عند ممارسة النشاط الاقتصادي فيها.","title":"الإعفاء أو التخفيض من ضريبة الدخل","memo":"⭐ إعفاء أو تخفيض لا يقل عن (٣٠%) من ضريبة الدخل\n⭐ للأنشطة في المناطق الأقل نمواً أو المشاريع التي تشغل (٢٥٠) أردنياً على الأقل\n⭐ لمدة (٥) سنوات من تاريخ التشغيل الفعلي حداً أعلى\n⭐ التفاصيل (الأنشطة، النسب، المناطق الأقل نمواً) تحدد بمقتضى نظام","qs":[{"q":"الحد الأدنى لنسبة تخفيض ضريبة الدخل وفق المادة (١٠):","o":["٣٠%","٢٥%","٥٠%","٢٠%"],"a":0},{"q":"يستفيد من الإعفاء أو التخفيض من ضريبة الدخل المشروع الذي يشغل على الأقل:","o":["٢٥٠ أردنياً","٣٥٠ أردنياً","١٠٠ أردني","٥٠ أردنياً"],"a":0},{"q":"الحد الأعلى لمدة الإعفاء أو التخفيض من ضريبة الدخل وفق المادة (١٠):","o":["خمس سنوات من تاريخ التشغيل الفعلي","سبع سنوات من تاريخ التشغيل الفعلي","خمس سنوات من تاريخ التسجيل","عشر سنوات من تاريخ نفاذ القانون"],"a":0}]},{"n":"11","chapter":"الفصل الثالث - الحوافز الممنوحة خارج المناطق التنموية والمناطق الحرة","notes":[],"source":"اذا تبين أن السلع والخدمات التي تم اعفاؤها من الرسوم والضرائب أو التي استفادت من أي تخفيض وفقا لأحكام المادتين (٩) و(١٠) من هذا القانون قد تم بيعها أو التنازل عنها أو التصرف فيها أو استعملت في غير النشاط الاقتصادي أو في غير الغايات التي تم منح الإعفاء من أجلها فيتوجب دفع الضرائب والرسوم المتحققة وفق أحكام التشريعات النافذة إضافة إلى الغرامات المنصوص عليها في تلك التشريعات.","title":"استعمال السلع المعفاة في غير غاياتها","memo":"⭐ إذا بيعت السلع والخدمات المعفاة وفق المادتين (٩) و(١٠) أو تم التنازل عنها أو استعملت في غير النشاط أو الغاية\n⭐ يتوجب دفع الضرائب والرسوم المتحققة وفق التشريعات النافذة إضافة إلى الغرامات المنصوص عليها فيها","qs":[{"q":"مستثمر استفاد من إعفاء جمركي على آلات لنشاطه الاقتصادي ثم باعها لطرف آخر، فإن الأثر القانوني هو:","o":["دفع الضرائب والرسوم المتحققة إضافة إلى الغرامات المنصوص عليها في التشريعات النافذة","إلغاء تسجيل المشروع حكماً","دفع الرسوم فقط دون أي غرامات","لا يترتب عليه شيء ما دام قد مارس النشاط فترة من الزمن"],"a":0},{"q":"تنطبق أحكام المادة (١١) على السلع والخدمات التي أعفيت أو خفضت وفقاً لأحكام:","o":["المادتين (٩) و(١٠)","المادتين (١٣) و(١٤)","المادتين (٢٩) و(٣٠)","المادة (٣١)"],"a":0}]},{"n":"12","chapter":"ثانياً : الحوافز الاضافية","notes":[],"source":"أ- يشكل مجلس الوزراء من بين اعضائه لجنة تسمى (لجنة الحوافز والإعفاءات ) على أن تضم في عضويتها الوزير ووزير التخطيط والتعاون الدولي ووزير الصناعة والتجارة والتموين ووزير المالية على ان يتضمن قرار التشكيل تسمية رئيسها وباقي الأعضاء.\nب- يحظر على رئيس لجنة الحوافز والاعفاءات او أي عضو من أعضائها أن يشترك في اتخاذ أي قرار يتعلق بنشاط اقتصادي أو صندوق استثمار أو صندوق استثمار مشترك تتحقق له او لأزواجه او فروعه او لأقاربه حتى الدرجة الثانية فيها منفعة مباشرة او غير مباشرة وعلى كل منهم الافصاح عن اي منافع قد تتحقق لأي منهم تحت طائلة المسؤولية القانونية.","title":"لجنة الحوافز والإعفاءات","memo":"⭐ يشكلها مجلس الوزراء من بين أعضائه\n⭐ تضم: وزير الاستثمار، وزير التخطيط والتعاون الدولي، وزير الصناعة والتجارة والتموين، وزير المالية\n⭐ قرار التشكيل يسمي رئيسها وباقي الأعضاء\n⭐ يحظر الاشتراك في قرار يحقق منفعة له أو لأزواجه أو فروعه أو أقاربه حتى الدرجة الثانية، مع واجب الإفصاح","qs":[{"q":"تشكل لجنة الحوافز والإعفاءات من قبل:","o":["مجلس الوزراء من بين أعضائه","وزير الاستثمار","مجلس الاستثمار","رئيس الوزراء من بين ممثلي القطاع الخاص"],"a":0},{"q":"أي مما يلي ليس من الأعضاء المنصوص عليهم في لجنة الحوافز والإعفاءات؟","o":["محافظ البنك المركزي الأردني","وزير المالية","وزير التخطيط والتعاون الدولي","وزير الصناعة والتجارة والتموين"],"a":0},{"q":"يحظر على عضو لجنة الحوافز والإعفاءات الاشتراك في قرار تتحقق فيه منفعة لأقاربه حتى الدرجة:","o":["الثانية","الأولى","الثالثة","الرابعة"],"a":0}]},{"n":"13","chapter":"الفصل الثالث - الحوافز الممنوحة خارج المناطق التنموية والمناطق الحرة","notes":[],"source":"أ- على الرغم مما ورد في اي تشريع آخر لمجلس الوزراء بناء على تنسيب لجنة الحوافز والإعفاءات، اعتماد أي حوافز أو مزايا أو إعفاءات للأنشطة الاقتصادية في أي منطقة من مناطق المملكة بما في ذلك ما يلي:-\n١-إعفاءات وحوافز متعلقة بسعر بدل البيع أو الإيجار للأراضي المملوكة للخزينة العامة لغايات إقامة الانشطة الاقتصادية\n٢- دعم كلف الطاقة والمياه ودعم مشاريع الطاقة المتجددة\n٣- السماح للمستثمرين بتخصيم كلف إنشاء خدمات البنية التحتية التي قاموا بإيصالها للنشاط الاقتصادي من الذمم المستحقة في حال تشغيل المشروع خلال مدة زمنية معينة.\n٤- منح إعفاءات أو تخفيضات ضريبية أو جمركية مقابل تشغيل حد أدنى من العمالة الأردنية.\nب- يراعى في منح الحوافز والإعفاءات والمزايا المشار إليها في الفقرة (أ) من هذه المادة المعايير التالية وبما لا يؤثر على المنافسة العادلة:-\n١-تشغيل ما لا يقل عن (٣٥٠) من الأردنيين.\n٢-تشغيل عاملات اردنيات بما لا يقل عن (٥٠%) من اجمالي العمالة على ان لا يقل العدد عن (٥٠) عاملة أردنية.\n٣-الانشطة الاقتصادية التي تستهدف الاسواق التصديرية بنسبة لا تقل عن (٥٠%)\n٤-الانشطة ذات القيمة المضافة المحلية وبنسبة لا تقل عن (٥٠%)\n٥-الانشطة التي تستهدف نقل المعرفة والتكنولوجيا والتحول الرقمي.\n٦-الانشطة الاقتصادية الاستراتيجية.\n٧-الانشطة المدرجة ضمن مشروعات الشراكة بين القطاعين العام والخاص.\n٨-الأنشطة التي تستهدف الأطراف ومناطق الفقر وتنمية وخدمة المجتمع المحلي.\nج- يتم تحديد أسس ومعايير الاستحقاق والمدد وإجراءات منح الحوافز والإعفاءات والمزايا المشار إليها في الفقرة (أ) من هذه المادة بموجب نظام يصدر وفقا لأحكام هذا القانون.\nد- على لجنة الحوافز والاعفاءات مراجعة أي ازدواج ضريبي لصناديق الاستثمار او صناديق الاستثمار المشترك عن الاستثمار المباشر او غير المباشر ومعالجة هذا الازدواج باستيفاء ضريبة الدخل على الحصص او مساهمي الصندوق للأشخاص الاعتباريين وفقاً لنشاطهم وعلى أن يسري هذا الاجراء للسنوات المالية اللاحقة ورفع الامر الى مجلس الوزراء لاتخاذ القرار المناسب بهذا الشأن.\nهـ- تصدر لجنة الحوافز والإعفاءات قراراتها بأغلبية أعضائها خلال مدة لا تتجاوز(١٥) يوم عمل من تاريخ تقديم الطلب المستكمل للشروط.\nو- تتولى الوزارة أمانة سر لجنة الحوافز والإعفاءات وتنظم كافة الشؤون المتعلقة بها وباجتماعاتها بمقتضى تعليمات تصدرها لهذه الغاية.","title":"الحوافز الإضافية ومعايير منحها","memo":"⭐ يعتمدها مجلس الوزراء بتنسيب لجنة الحوافز والإعفاءات (أراضي الخزينة، دعم الطاقة والمياه، تخصيم كلف البنية التحتية، إعفاءات مقابل تشغيل أردنيين)\n⭐ المعايير: تشغيل (٣٥٠) أردنياً على الأقل؛ أو عاملات أردنيات لا يقل عن (٥٠%) وبعدد لا يقل عن (٥٠)\n⭐ التصدير لا يقل عن (٥٠%)؛ القيمة المضافة المحلية لا تقل عن (٥٠%)\n⭐ تصدر اللجنة قراراتها بأغلبية أعضائها خلال (١٥) يوم عمل من تقديم الطلب المستكمل؛ والوزارة أمانة سرها","qs":[{"q":"من معايير منح الحوافز الإضافية تشغيل ما لا يقل عن:","o":["٣٥٠ أردنياً","٢٥٠ أردنياً","٥٠٠ أردني","١٠٠ أردني"],"a":0},{"q":"مشروع يشغل عاملات أردنيات بنسبة (٦٠%) من إجمالي العمالة وعددهن (٤٠) عاملة، فإنه وفق معيار تشغيل الأردنيات:","o":["لا يحقق المعيار لأن العدد يقل عن (٥٠) عاملة","يحقق المعيار لأن النسبة تزيد على (٥٠%)","يحقق المعيار لأن النسبة تزيد على (٣٠%)","لا يحقق المعيار لأن النسبة يجب ألا تقل عن (٧٥%)"],"a":0},{"q":"تصدر لجنة الحوافز والإعفاءات قراراتها خلال مدة لا تتجاوز:","o":["١٥ يوم عمل من تاريخ تقديم الطلب المستكمل للشروط","٢٠ يوم عمل من تاريخ تقديم الطلب","٣٠ يوماً من تاريخ تقديم الطلب","١٠ أيام عمل من تاريخ تقديم الطلب المستكمل"],"a":0},{"q":"الحد الأدنى لنسبة استهداف الأسواق التصديرية كمعيار لمنح الحوافز الإضافية:","o":["٥٠%","٣٠%","٢٥%","٤٠%"],"a":0}]},{"n":"14","chapter":"الفصل الثالث - الحوافز الممنوحة خارج المناطق التنموية والمناطق الحرة","notes":[],"source":"أ- على الرغم مما ورد في أي تشريع آخر، لمجلس الوزراء بناء على تنسيب لجنة الحوافز والإعفاءات منح موافقة واحدة لإقامة مشروع لمستثمر إذا كان هذا المشروع يشكل نشاطا اقتصاديا استراتيجيا يسهم في تحقيق التنمية المستدامة\nب- تعتبر الموافقة الصادرة بمقتضى الفقرة (أ) من هذه المادة بديلا عن أي ترخيص أو تصريح أو إذن يتطلبه أي تشريع\nج- لا يجوز التنازل عن الموافقة الممنوحة بمقتضى الفقرة (أ) من هذه المادة لإقامة المشروع او نقل ملكيته او تأجيره للغير الا بموافقة مجلس الوزراء بناء على تنسيب لجنة الحوافز والإعفاءات.\nد- تنظم شروط وإجراءات الحصول على الموافقة الواحدة بمقتضى نظام.","title":"الموافقة الواحدة للمشاريع الاستراتيجية","memo":"⭐ يمنحها مجلس الوزراء بتنسيب لجنة الحوافز والإعفاءات لمشروع يشكل نشاطاً اقتصادياً استراتيجياً يسهم في التنمية المستدامة\n⭐ تعتبر بديلاً عن أي ترخيص أو تصريح أو إذن يتطلبه أي تشريع\n⭐ لا يجوز التنازل عنها أو نقل ملكية المشروع أو تأجيره للغير إلا بموافقة مجلس الوزراء بتنسيب اللجنة\n⭐ شروطها وإجراءاتها تنظم بمقتضى نظام","qs":[{"q":"الجهة المختصة بمنح الموافقة الواحدة لإقامة مشروع استراتيجي:","o":["مجلس الوزراء بناء على تنسيب لجنة الحوافز والإعفاءات","وزير الاستثمار بناء على تنسيب أمين عام الوزارة","مجلس الاستثمار","لجنة الحوافز والإعفاءات منفردة"],"a":0},{"q":"تعتبر الموافقة الواحدة الممنوحة بموجب المادة (١٤):","o":["بديلاً عن أي ترخيص أو تصريح أو إذن يتطلبه أي تشريع","موافقة مبدئية يلزم بعدها الحصول على التراخيص كافة","بديلاً عن رخصة المهن فقط","مؤقتة لمدة سنة واحدة"],"a":0},{"q":"مستثمر حصل على موافقة واحدة لمشروع استراتيجي ويرغب بتأجير المشروع للغير، فعليه الحصول على:","o":["موافقة مجلس الوزراء بناء على تنسيب لجنة الحوافز والإعفاءات","موافقة وزير الاستثمار فقط","موافقة لجنة التظلمات","لا يحتاج لأي موافقة"],"a":0}]},{"n":"15","chapter":"الفصل الثالث - الحوافز الممنوحة خارج المناطق التنموية والمناطق الحرة","notes":[],"source":"أ- إذا تم تعديل أو تغيير الأحكام التشريعية أو التنظيمية ونجم عن ذلك التعديل أو التغيير أثر سلبي على المستثمر الذي تبلغ استثماراته في مشروع واحد خمسة ملايين دينار فأكثر أو قام بتوظيف مائتين وخمسين اردنياً فأكثر فيحق له المطالبة بعدم تطبيق تلك الاحكام في مواجهته ولمدة سبع سنوات من تاريخ تحقيقه لأي من هذين الشرطين.\nب- لغايات تطبيق أحكام الفقرة (أ) من هذه المادة، على المستثمر توجيه إخطار خطي للوزارة خلال مدة لا تتجاوز ستة أشهر من تاريخ اجراء التعديل أو التغيير التشريعي او التنظيمي يتضمن ما يلي -\n١-مضمون التعديل أو التغيير التشريعي أو التنظيمي والأثر السلبي الذي لحق او سيلحق به نتيجة لذلك.\n٢-إرفاق الوثائق التي تثبت تحقيقه للشروط الواردة في الفقرة (أ) من هذه المادة.\n٣-طلب عدم تطبيق أحكام التعديل أو التغيير التشريعي أو التنظيمي عليه.\nج- على الوزارة خلال (٢٠) يوم عمل من تاريخ استلام الإخطار المشار إليه في الفقرة (ب) من هذه المادة دراسة الطلب والتوصية لمجلس الوزراء لاتخاذ القرار المناسب.\nد- لمجلس الوزراء اتخاذ قرار بعدم تطبيق التعديل او التغيير التشريعي او التنظيمي او أي منها على المستثمر.\nهـ- تعُلم الوزارة المستثمر والجهة الرسمية المعنية بقرار مجلس الوزراء.","title":"الاستقرار التشريعي للمستثمر","memo":"⭐ لمن تبلغ استثماراته في مشروع واحد (٥) ملايين دينار فأكثر أو وظّف (٢٥٠) أردنياً فأكثر\n⭐ حق المطالبة بعدم تطبيق التعديل التشريعي/التنظيمي السلبي عليه لمدة (٧) سنوات من تاريخ تحقيق أي من الشرطين\n⭐ إخطار خطي للوزارة خلال (٦) أشهر من تاريخ التعديل\n⭐ الوزارة تدرس وتوصي خلال (٢٠) يوم عمل، والقرار لمجلس الوزراء","qs":[{"q":"يحق للمستثمر المطالبة بعدم تطبيق التعديلات التشريعية ذات الأثر السلبي عليه إذا بلغت استثماراته في مشروع واحد:","o":["خمسة ملايين دينار فأكثر","مليون دينار فأكثر","عشرة ملايين دينار فأكثر","ثلاثة ملايين دينار فأكثر"],"a":0},{"q":"مدة عدم تطبيق التعديل التشريعي السلبي على المستثمر المستوفي للشروط:","o":["سبع سنوات من تاريخ تحقيقه لأي من الشرطين","خمس سنوات من تاريخ إجراء التعديل","عشر سنوات من تاريخ تحقيقه للشرطين معاً","سبع سنوات من تاريخ نفاذ القانون"],"a":0},{"q":"يجب على المستثمر توجيه إخطار خطي للوزارة بطلب عدم تطبيق التعديل خلال مدة لا تتجاوز:","o":["ستة أشهر من تاريخ إجراء التعديل","ثلاثة أشهر من تاريخ إجراء التعديل","(٢٠) يوم عمل من تاريخ إجراء التعديل","سنة من تاريخ إجراء التعديل"],"a":0},{"q":"الجهة المختصة باتخاذ قرار عدم تطبيق التعديل التشريعي على المستثمر:","o":["مجلس الوزراء","وزارة الاستثمار","مجلس الاستثمار","لجنة التظلمات"],"a":0}]},{"n":"16","chapter":"الفصل الثالث - الحوافز الممنوحة خارج المناطق التنموية والمناطق الحرة","notes":[],"source":"مع مراعاة أي مزايا أو إعفاءات أو حوافز يمنحها هذا الفصل للنشاط الاقتصادي، تبقى الأنشطة الاقتصادية التي تتمتع بمزايا أو إعفاءات جمركية أو ضريبية أو حوافز مالية بمقتضى قانون الاستثمار رقم (٣٠) لسنة ٢٠١٤ وأي أنظمة أو تعليمات أو قرارات صادرة بمقتضاه مستفيدة من تلك الإعفاءات والمزايا حتى نهاية مدة الإعفاء الممنوح لها بموجب تلك التشريعات وبالشروط الواردة فيها أو لسبع سنوات من تاريخ نفاذ أحكام هذا القانون للإعفاءات التي لم تحدد بمدة.","title":"الحقوق المكتسبة بموجب قانون الاستثمار السابق","memo":"⭐ الأنشطة المتمتعة بإعفاءات بموجب قانون الاستثمار رقم (٣٠) لسنة ٢٠١٤ تبقى مستفيدة حتى نهاية مدة الإعفاء وبالشروط الواردة فيها\n⭐ الإعفاءات غير المحددة بمدة: تستمر (٧) سنوات من تاريخ نفاذ هذا القانون","qs":[{"q":"الإعفاءات الممنوحة بموجب قانون الاستثمار رقم (٣٠) لسنة ٢٠١٤ وغير المحددة بمدة تستمر:","o":["سبع سنوات من تاريخ نفاذ أحكام هذا القانون","خمس سنوات من تاريخ نفاذ أحكام هذا القانون","إلى أجل غير محدد","تنتهي بنفاذ هذا القانون"],"a":0},{"q":"نشاط اقتصادي يتمتع بإعفاء محدد المدة بموجب قانون الاستثمار لسنة ٢٠١٤، فإنه:","o":["يبقى مستفيداً منه حتى نهاية مدة الإعفاء وبالشروط الواردة في تلك التشريعات","يفقد الإعفاء فور نفاذ القانون الجديد","يستفيد منه لمدة سبع سنوات فقط أياً كانت مدته","يحتاج لموافقة جديدة من لجنة الحوافز والإعفاءات"],"a":0}]},{"n":"17","chapter":"الفصل الثالث - الحوافز الممنوحة خارج المناطق التنموية والمناطق الحرة","notes":[],"source":"أ- يمنح المستثمر وعائلته والعاملون لديه من الإدارة العليا (بطاقة تعريف مستثمر) لتبسيط وتسهيل اجراءات المستثمر لدى الجهات الرسمية وتسهيل دخول وخروج حاملها من وإلى المملكة.\nب- تنظم أسس وتصنيفات وشروط الحصول على بطاقة تعريف المستثمر بمقتضى تعليمات.","title":"بطاقة تعريف المستثمر","memo":"⭐ تمنح للمستثمر وعائلته والعاملين لديه من الإدارة العليا\n⭐ لتبسيط إجراءاته لدى الجهات الرسمية وتسهيل الدخول والخروج من وإلى المملكة\n⭐ أسسها وتصنيفاتها وشروطها بمقتضى تعليمات","qs":[{"q":"تمنح بطاقة تعريف المستثمر لـ:","o":["المستثمر وعائلته والعاملين لديه من الإدارة العليا","المستثمر غير الأردني فقط","المستثمر وجميع العاملين لديه","المستثمر الذي تبلغ استثماراته خمسة ملايين دينار فأكثر فقط"],"a":0},{"q":"تنظم أسس وشروط الحصول على بطاقة تعريف المستثمر بمقتضى:","o":["تعليمات","نظام","قرار من مجلس الوزراء","قانون خاص"],"a":0}]},{"n":"18","chapter":"الفصل الرابع - المناطق التنموية والمناطق الحرة","notes":[],"source":"أ-١- تنشأ المنطقة بقرار من مجلس الوزراء بناء على تنسيب الوزير ويتم تعيين حدودها أو تعديلها أو الغاؤها بالطريقة ذاتها مع حفظ الحقوق المكتسبة في حالة التعديل أو الإلغاء ويتم تحديد المعايير والشروط والإجراءات المطلوبة لذلك بموجب نظام.\n٢- تنشر القرارات المشار إليها في البند (١) من هذه الفقرة في الجريدة الرسمية.\nب- يجوز ان تكون المنطقة الحرة المنشأة وفق احكام الفقرة (أ) من هذه المادة داخل المنطقة التنموية.","title":"إنشاء المناطق التنموية والحرة","memo":"⭐ تنشأ المنطقة بقرار من مجلس الوزراء بناء على تنسيب الوزير، وكذلك تعيين حدودها وتعديلها وإلغاؤها مع حفظ الحقوق المكتسبة\n⭐ تنشر القرارات في الجريدة الرسمية؛ والمعايير والشروط بموجب نظام\n⭐ يجوز أن تكون المنطقة الحرة داخل المنطقة التنموية","qs":[{"q":"تنشأ المنطقة التنموية أو الحرة بقرار من:","o":["مجلس الوزراء بناء على تنسيب الوزير","الوزير بناء على تنسيب المطور الرئيسي","مجلس الاستثمار","لجنة الحوافز والإعفاءات"],"a":0},{"q":"وفقاً للمادة (١٨)، فإن المنطقة الحرة:","o":["يجوز أن تكون داخل المنطقة التنموية","لا يجوز أن تكون داخل المنطقة التنموية","يجب أن تكون داخل المنطقة التنموية دائماً","لا تنشأ إلا داخل منطقة العقبة الاقتصادية الخاصة"],"a":0},{"q":"عند إلغاء المنطقة أو تعديل حدودها:","o":["تحفظ الحقوق المكتسبة","تسقط جميع الحقوق المكتسبة","تحفظ الحقوق المكتسبة للمطور الرئيسي فقط","يعوض المستثمرون بالقيمة السوقية العادلة حكماً"],"a":0}]},{"n":"19","chapter":"الفصل الرابع - المناطق التنموية والمناطق الحرة","notes":[],"source":"أ -عند إنشاء المنطقة وفقاً لأحكام هذا الفصل، تنتقل ملكية الأراضي داخلها من الخزينة العامة إلى الوزارة وتسجل باسمها.\nب- للوزارة تأجير أو بيع أي من الاراضي المسجلة باسمها داخل المنطقة الى المطور الرئيسي لتلك المنطقة، وفقا لاتفاقية التطوير التي يوافق عليها مجلس الوزراء وبالبدل الذي يحدده.\nج- على الرغم مما ورد في الفقرة (ب) من هذه المادة، لا يجوز بيع الأراضي المخصصة للنفع العام وأراضي انحسار البحر للمطور الرئيسي وعليه تطويرها وفق ما يحدد في اتفاقية التطوير.\nد- مع مراعاة المادة (٢٢) من هذا القانون، اذا لم يقم المطور الرئيسي بإنجاز اعمال التطوير في المنطقة على الوزارة مطالبته بغرامة نسبتها اثنان بالمائة (٢%) من قيمة الاراضي السوقية التي لم يتم تطويرها وذلك عن كل سنة تأخير عن الجدول الزمني المحدد في اتفاقية التطوير.\nهـ- مع مراعاة الفقرة (ج) من هذه المادة، للمطور الرئيسي تأجير أو بيع الأراضي في المنطقة الى المؤسسة المسجلة في تلك المنطقة أو الى المؤسسات الرسمية العامة او المؤسسات العامة أو الجهات التي تدير مرافق عامة او تقدم خدمات البنى التحتية للمنطقة على ان يتم البيع بموافقة مجلس الوزراء بناء على تنسيب الوزير في الاراضي التي كانت مملوكة للوزارة وانتقلت للمطور الرئيسي.\nو- على الرغم مما ورد في أي تشريع آخر:-\n١-تكون مدة الإيجار في المنطقة بالنسبة للعقود المبرمة بين الوزارة والمطور الرئيسي وبين المطور الرئيسي والمؤسسة المسجلة ثلاثين سنة قابلة للتجديد لمدة مماثلة باتفاق الطرفين ويحق للفريقين تجديدها لثلاثين سنة اضافية بموافقة مجلس الوزراء. ٢-توثق عقود الوعد بالبيع للأراضي في المنطقة لدى دائرة الاراضي والمساحة على ان تستوفي رسما مقداره واحد بالألف من قيمة هذه العقود يدفع من قبل المشتري.","title":"أراضي المنطقة وبيعها وتأجيرها","memo":"⭐ تنتقل ملكية الأراضي من الخزينة العامة إلى الوزارة وتسجل باسمها\n⭐ لا يجوز بيع أراضي النفع العام وأراضي انحسار البحر للمطور الرئيسي\n⭐ غرامة تأخير التطوير (٢%) من القيمة السوقية للأراضي غير المطورة عن كل سنة تأخير\n⭐ مدة الإيجار (٣٠) سنة قابلة للتجديد لمدة مماثلة + (٣٠) إضافية بموافقة مجلس الوزراء؛ رسم توثيق الوعد بالبيع واحد بالألف يدفعه المشتري","qs":[{"q":"عند إنشاء المنطقة تنتقل ملكية الأراضي داخلها من الخزينة العامة إلى:","o":["الوزارة","المطور الرئيسي","المؤسسة المسجلة","دائرة الأراضي والمساحة"],"a":0},{"q":"إذا تأخر المطور الرئيسي عن إنجاز أعمال التطوير وفق الجدول الزمني، تطالبه الوزارة بغرامة نسبتها:","o":["٢% من القيمة السوقية للأراضي غير المطورة عن كل سنة تأخير","٢% من القيمة السوقية لجميع أراضي المنطقة دفعة واحدة","٥% من القيمة السوقية للأراضي غير المطورة عن كل سنة تأخير","١% من قيمة اتفاقية التطوير عن كل سنة تأخير"],"a":0},{"q":"مدة الإيجار في المنطقة للعقود بين الوزارة والمطور الرئيسي:","o":["ثلاثون سنة قابلة للتجديد لمدة مماثلة","عشرون سنة قابلة للتجديد","خمسون سنة غير قابلة للتجديد","تسع وتسعون سنة"],"a":0},{"q":"رسم توثيق عقود الوعد بالبيع للأراضي في المنطقة لدى دائرة الأراضي والمساحة:","o":["واحد بالألف من قيمة العقد يدفعه المشتري","واحد بالألف من قيمة العقد يدفعه البائع","اثنان بالمائة من قيمة العقد يدفعه المشتري","مناصفة بين البائع والمشتري بنسبة واحد بالمائة"],"a":0}]},{"n":"20","chapter":"الفصل الرابع - المناطق التنموية والمناطق الحرة","notes":[],"source":"أ- يتولى المطور الرئيسي إدارة المنطقة وتطويرها وفقاً للشروط والأحكام والمعايير المنصوص عليها في هذا الفصل والأنظمة الصادرة لتنفيذه واتفاقية التطوير.\nب- يقوم المطور الرئيسي بتطوير وتشغيل وإدارة المنطقة سواء قام بذلك بنفسه أو من خلال الغير ولهذه الغاية يلتزم بما يلي:-\n١- تأمين التمويل اللازم لتطوير المنطقة وإدارتها وصيانتها.\n٢- إنشاء البنية التحتية الأساسية داخل المنطقة وإدامتها بما في ذلك الطرق والكهرباء والمياه والاتصالات والصرف الصحي وفقاً لاتفاقية التطوير.\n٣- تشييد المباني والقيام بالتحسينات وأعمال الصيانة واجراءات الأمن والحماية الضرورية وفقاً لاتفاقية التطوير.\n٤- تسويق المنطقة وترويجها.\n٥- توفير المتطلبات والاشتراطات البيئية وخدمات جمع النفايات والتخلص منها.\n٦- الرقابة على أعمال الإعمار وإعلام الوزارة لاتخاذ الاجراءات اللازمة في حال المخالفة.\n٧- أي أمور أخرى لازمة لتطوير المنطقة.","title":"مهام والتزامات المطور الرئيسي","memo":"⭐ يتولى إدارة المنطقة وتطويرها وفق القانون والأنظمة واتفاقية التطوير، بنفسه أو من خلال الغير\n⭐ يلتزم بتأمين التمويل وإنشاء البنية التحتية (طرق، كهرباء، مياه، اتصالات، صرف صحي)\n⭐ تسويق المنطقة، والمتطلبات البيئية وجمع النفايات، والرقابة على الإعمار وإعلام الوزارة بالمخالفة","qs":[{"q":"يقوم المطور الرئيسي بتطوير وتشغيل وإدارة المنطقة:","o":["بنفسه أو من خلال الغير","بنفسه حصراً","من خلال الوزارة فقط","من خلال المؤسسات المسجلة فقط"],"a":0},{"q":"أي مما يلي ليس من التزامات المطور الرئيسي وفق المادة (٢٠)؟","o":["تسجيل المؤسسات المسجلة وتجديد تسجيلها","تأمين التمويل اللازم لتطوير المنطقة وإدارتها وصيانتها","تسويق المنطقة وترويجها","توفير خدمات جمع النفايات والتخلص منها"],"a":0},{"q":"عند وجود مخالفة في أعمال الإعمار داخل المنطقة، يلتزم المطور الرئيسي بـ:","o":["إعلام الوزارة لاتخاذ الإجراءات اللازمة","إيقاع الغرامة على المخالف مباشرة","إحالة المخالف إلى المحكمة","إلغاء تسجيل المؤسسة المخالفة"],"a":0}]},{"n":"21","chapter":"الفصل الرابع - المناطق التنموية والمناطق الحرة","notes":[],"source":"يلتزم المطور الرئيسي باستكمال الاجراءات اللازمة لتسجيله مؤسسة مسجلة في المنطقة وفقاً لأحكام هذا الفصل والأنظمة الصادرة لتنفيذه.","title":"تسجيل المطور الرئيسي مؤسسة مسجلة","memo":"⭐ يلتزم المطور الرئيسي باستكمال إجراءات تسجيله مؤسسة مسجلة في المنطقة","qs":[{"q":"يلتزم المطور الرئيسي وفق المادة (٢١) بـ:","o":["استكمال الإجراءات اللازمة لتسجيله مؤسسة مسجلة في المنطقة","التسجيل لدى لجنة الحوافز والإعفاءات","الحصول على موافقة مجلس الاستثمار السنوية","التسجيل في منطقة العقبة الاقتصادية الخاصة"],"a":0}]},{"n":"22","chapter":"الفصل الرابع - المناطق التنموية والمناطق الحرة","notes":[],"source":"أ- على الرغم مما ورد في أي تشريع آخر، في حال إخلال المطور الرئيسي أو المؤسسة المسجلة بأحكام هذا الفصل والأنظمة الصادرة لتنفيذه والاتفاقيات ذات العلاقة:-\n١- للوزارة بموافقة مجلس الوزراء استرداد أراضيها التي انتقلت ملكيتها الى المطور الرئيسي كليا او جزئيا.\n٢- للمطور الرئيسي بموافقة مجلس الوزراء استرداد أراضيه التي انتقلت ملكيتها الى المؤسسة المسجلة كليا او جزئيا.\nب- تنظم أحكام وإجراءات وحالات استرداد الأراضي المشار إليها في الفقرة (أ) من هذه المادة بمقتضى نظام .","title":"استرداد الأراضي عند الإخلال","memo":"⭐ عند إخلال المطور الرئيسي: للوزارة بموافقة مجلس الوزراء استرداد أراضيها كلياً أو جزئياً\n⭐ عند إخلال المؤسسة المسجلة: للمطور الرئيسي بموافقة مجلس الوزراء استرداد أراضيه كلياً أو جزئياً\n⭐ أحكام وحالات الاسترداد بمقتضى نظام","qs":[{"q":"في حال إخلال المطور الرئيسي بأحكام القانون واتفاقية التطوير، يحق للوزارة استرداد أراضيها:","o":["بموافقة مجلس الوزراء كلياً أو جزئياً","بقرار من الوزير منفرداً كلياً فقط","بحكم قضائي فقط","بموافقة مجلس الاستثمار جزئياً فقط"],"a":0},{"q":"مؤسسة مسجلة أخلت بأحكام الاتفاقيات ذات العلاقة، فإن الجهة التي يحق لها استرداد الأراضي التي انتقلت إليها من المطور الرئيسي:","o":["المطور الرئيسي بموافقة مجلس الوزراء","الوزارة دون حاجة لأي موافقة","المطور الرئيسي بموافقة الوزير","دائرة الأراضي والمساحة"],"a":0}]},{"n":"23","chapter":"الفصل الرابع - المناطق التنموية والمناطق الحرة","notes":[],"source":"أ-على الرغم مما ورد في أي تشريع آخر، يشكل الوزير في المنطقة اللجان التي تمارس صلاحيات مجلس التنظيم الأعلى وصلاحيات اللجان المحلية و اللوائية على ان تكون اللجنة التي تمارس صلاحيات مجلس التنظيم الأعلى برئاسة الوزير.\nب- تمارس الوزارة داخل حدود المنطقة المهام والصلاحيات التالية :- ١-صلاحيات المجلس البلدي والجهات الأخرى المنصوص عليها في التشريعات النافذة ويمارس الوزير صلاحيات رئيس المجلس البلدي.\n٢-تنظيم المنطقة وفقاً لأحكام هذا الفصل والأنظمة الصادرة لتنفيذه ومنح الرخص التنظيمية والمهنية اللازمة لمن يرغب بممارسة نشاط اقتصادي فيها.\n٣-تأسيس وتسجيل الشخص في المنطقة الحرة لممارسة النشاط الاقتصادي داخل المملكة وخارجها وفق نظام.\n٤- تسجيل المؤسسة المسجلة وتجديد تسجيلها وتعليقه وإلغاؤه وفق نظام.\n٥-بيع أو مصادرة أو إتلاف أو تملك المواد والبضائع التي تم التخلي عنها أو تركها دون مطالبة في المنطقة وفقاً لأسس وإجراءات تحدد بموجب تعليمات.\n٦-حماية البيئة ومصادر المياه والموارد الطبيعية والتنوع الحيوي بما ينسجم مع التشريعات النافذة.\n٧-استملاك الأراضي والعقارات اللازمة لتطوير المنطقة وفقاً لأحكام قانون الملكية العقارية.\n٨-مراقبة تنفيذ تطوير المنطقة.\n٩-تحصيل الرسوم والعوائد والغرامات المحددة بمقتضى الأنظمة الصادرة لتنفيذ أحكام هذا الفصل أو بمقتضى التشريعات النافذة في المنطقة وتحديد بدل الخدمات وكيفية استيفائه.\nج- يكون للوزارة حق منح الوصول للخدمات العامة بالتنسيق مع مقدميها والمطور الرئيسي.","title":"صلاحيات الوزارة داخل المنطقة","memo":"⭐ يشكل الوزير لجاناً تمارس صلاحيات مجلس التنظيم الأعلى (برئاسة الوزير) واللجان المحلية واللوائية\n⭐ تمارس الوزارة صلاحيات المجلس البلدي ويمارس الوزير صلاحيات رئيس المجلس البلدي\n⭐ تسجيل المؤسسة المسجلة وتجديده وتعليقه وإلغاؤه وفق نظام؛ والتصرف بالبضائع المتروكة وفق تعليمات\n⭐ استملاك الأراضي وفق قانون الملكية العقارية، وتحصيل الرسوم والغرامات وتحديد بدل الخدمات","qs":[{"q":"يرأس اللجنة التي تمارس صلاحيات مجلس التنظيم الأعلى داخل المنطقة:","o":["الوزير","أمين عام الوزارة","المطور الرئيسي","رئيس الوزراء"],"a":0},{"q":"داخل حدود المنطقة يمارس صلاحيات رئيس المجلس البلدي:","o":["الوزير","أمين عام الوزارة","المطور الرئيسي","وزير الإدارة المحلية"],"a":0},{"q":"يتم استملاك الأراضي والعقارات اللازمة لتطوير المنطقة وفقاً لأحكام:","o":["قانون الملكية العقارية","قانون البيئة الاستثمارية مباشرة","قانون الاستملاك المؤقت","اتفاقية التطوير"],"a":0}]},{"n":"24","chapter":"الفصل الرابع - المناطق التنموية والمناطق الحرة","notes":[],"source":"للوزارة بموافقة مجلس الوزراء ووفقاً لإجراءات ومتطلبات تحددها أن تعهد بأي من مهامها وصلاحياتها المتعلقة بالمنطقة إلى أي جهة رسمية أو شركة مملوكة بالكامل للحكومة أو إلى المطور الرئيسي لتلك المنطقة.","title":"تفويض مهام الوزارة في المنطقة","memo":"⭐ للوزارة بموافقة مجلس الوزراء أن تعهد بأي من مهامها المتعلقة بالمنطقة\n⭐ إلى أي جهة رسمية أو شركة مملوكة بالكامل للحكومة أو إلى المطور الرئيسي","qs":[{"q":"للوزارة أن تعهد بأي من مهامها وصلاحياتها المتعلقة بالمنطقة إلى المطور الرئيسي بموافقة:","o":["مجلس الوزراء","مجلس الاستثمار","الوزير","لجنة الحوافز والإعفاءات"],"a":0},{"q":"أي مما يلي لا يجوز للوزارة أن تعهد إليه بمهامها المتعلقة بالمنطقة وفق المادة (٢٤)؟","o":["شركة خاصة تملك الحكومة جزءاً من رأسمالها","جهة رسمية","شركة مملوكة بالكامل للحكومة","المطور الرئيسي لتلك المنطقة"],"a":0}]},{"n":"25","chapter":"الفصل الرابع - المناطق التنموية والمناطق الحرة","notes":[],"source":"أ- على الرغم مما ورد في أي تشريع آخر، يجوز لأي مؤسسة مسجلة في المنطقة ممارسة النشاط الاقتصادي الذي رخصت من أجله وفقا لأحكام هذا الفصل والانظمة الصادرة لتنفيذه واتفاقية التطوير وذلك باستثناء ما يتم حظره او تقييد ممارسته في المنطقة بمقتضى نظام.\nب- يتمتع المطور الرئيسي والمؤسسة المسجلة في المنطقة بكافة الحقوق اللازمة لممارسة النشاط الاقتصادي بما في ذلك:-\n١- القيام بكافة التصرفات المتعلقة ببيع وشراء واستئجار وتأجير وادارة ونقل ملكية أي أرض أو منشآت داخل حدود المنطقة وذلك بما يتفق واحكام هذا الفصل على ان لا يتعارض مع التشريعات الناظمة لملكية الاراضي في المملكة.\n٢- كافة أنواع التسهيلات والإعفاءات المقررة بموجب أحكام هذا الفصل والانظمة والتعليمات الصادرة لتنفيذه.\n٣- التعاقد مع الموظفين والعمال وفق الأنظمة والتعليمات الصادرة لتنفيذ أحكام هذا الفصل.\n٤- التعاقد لإدارة العقارات الواقعة ضمن المنطقة.\n٥- أي حقوق ومزايا أخرى يمنحها هذا الفصل والأنظمة الصادرة لتنفيذه أو أي قانون آخر للمؤسسة المسجلة.","title":"حقوق المطور الرئيسي والمؤسسة المسجلة","memo":"⭐ يجوز للمؤسسة المسجلة ممارسة النشاط المرخص باستثناء ما يحظر أو يقيد بمقتضى نظام\n⭐ حق التصرف ببيع وشراء واستئجار وتأجير ونقل ملكية الأراضي والمنشآت دون تعارض مع تشريعات ملكية الأراضي\n⭐ التسهيلات والإعفاءات، والتعاقد مع الموظفين، والتعاقد لإدارة العقارات","qs":[{"q":"يجوز للمؤسسة المسجلة ممارسة النشاط الذي رخصت من أجله باستثناء ما يتم حظره أو تقييده بمقتضى:","o":["نظام","تعليمات يصدرها المطور الرئيسي","قرار من مجلس الاستثمار","اتفاقية التطوير فقط"],"a":0},{"q":"يمارس المطور الرئيسي والمؤسسة المسجلة التصرفات المتعلقة بنقل ملكية الأراضي داخل المنطقة بشرط:","o":["ألا يتعارض ذلك مع التشريعات الناظمة لملكية الأراضي في المملكة","الحصول على موافقة مجلس الوزراء في كل حالة","أن يكون المشتري أردني الجنسية","أن يتم ذلك بعد مرور خمس سنوات على التسجيل"],"a":0}]},{"n":"26","chapter":"الفصل الرابع - المناطق التنموية والمناطق الحرة","notes":[],"source":"على الرغم مما ورد في أي تشريع آخر، تعتبر الرخصة الممنوحة لممارسة النشاط الاقتصادي في المنطقة وفقًا لأحكام هذا الفصل والأنظمة والتعليمات الصادرة لتنفيذه بمثابة رخصة مهن.","title":"الرخصة في المنطقة بمثابة رخصة مهن","memo":"⭐ الرخصة الممنوحة لممارسة النشاط الاقتصادي في المنطقة وفق هذا الفصل تعتبر بمثابة رخصة مهن","qs":[{"q":"تعتبر الرخصة الممنوحة لممارسة النشاط الاقتصادي في المنطقة وفقاً لأحكام القانون:","o":["بمثابة رخصة مهن","بديلاً عن السجل التجاري","موافقة واحدة لمشروع استراتيجي","بطاقة تعريف مستثمر"],"a":0},{"q":"مؤسسة مسجلة حصلت على رخصة لممارسة نشاطها الاقتصادي في المنطقة التنموية وفقاً لأحكام القانون، فإنها فيما يتعلق برخصة المهن:","o":["تعتبر رخصتها بمثابة رخصة مهن","يلزمها الحصول على رخصة مهن مستقلة من البلدية","يلزمها الحصول على رخصة مهن من المطور الرئيسي","تعفى من الترخيص كلياً"],"a":0}]},{"n":"27","chapter":"الفصل الرابع - المناطق التنموية والمناطق الحرة","notes":[],"source":"أ- على الرغم مما ورد في أي تشريع آخر، لا تطبق في المنطقة أي قيود متعلقة بنسبة رأس المال الأجنبي .\nب- يطبق في المنطقة التنموية قانون الاستيراد والتصدير ولهذه الغاية يمارس الوزير صلاحيات وزير الصناعة والتجارة والتموين المنصوص عليها في ذلك القانون .","title":"رأس المال الأجنبي والاستيراد والتصدير","memo":"⭐ لا تطبق في المنطقة أي قيود متعلقة بنسبة رأس المال الأجنبي\n⭐ يطبق في المنطقة التنموية قانون الاستيراد والتصدير، ويمارس الوزير صلاحيات وزير الصناعة والتجارة والتموين فيه","qs":[{"q":"فيما يتعلق بنسبة رأس المال الأجنبي في المنطقة:","o":["لا تطبق أي قيود متعلقة بنسبة رأس المال الأجنبي","لا يجوز أن تتجاوز (٤٩%)","لا يجوز أن تتجاوز (٥٠%) إلا بموافقة مجلس الوزراء","تحدد بموجب اتفاقية التطوير"],"a":0},{"q":"عند تطبيق قانون الاستيراد والتصدير في المنطقة التنموية، يمارس صلاحيات وزير الصناعة والتجارة والتموين:","o":["وزير الاستثمار","المطور الرئيسي","أمين عام وزارة الاستثمار","وزير المالية"],"a":0}]},{"n":"28","chapter":"الفصل الرابع - المناطق التنموية والمناطق الحرة","notes":[],"source":"تحدد أسس منح الإقامة للمستثمرين في المؤسسة المسجلة والمديرين والموظفين العاملين فيها وأفراد أسرهم بمقتضى نظام يراعي نسبة تشغيل الأردنيين وتنمية المحافظات.","title":"الإقامة في المنطقة","memo":"⭐ أسس منح الإقامة للمستثمرين في المؤسسة المسجلة ومديريها وموظفيها وأسرهم تحدد بمقتضى نظام\n⭐ يراعي النظام نسبة تشغيل الأردنيين وتنمية المحافظات","qs":[{"q":"تحدد أسس منح الإقامة للمستثمرين في المؤسسة المسجلة والعاملين فيها وأفراد أسرهم بمقتضى:","o":["نظام يراعي نسبة تشغيل الأردنيين وتنمية المحافظات","تعليمات يصدرها المطور الرئيسي","قرار من وزير الداخلية دون قيود","اتفاقية التطوير"],"a":0},{"q":"من الاعتبارات التي يراعيها نظام منح الإقامة في المنطقة:","o":["نسبة تشغيل الأردنيين","حجم صادرات المؤسسة المسجلة","مدة الإيجار في المنطقة","نسبة رأس المال الأجنبي"],"a":0}]},{"n":"29","chapter":"الفصل الرابع - المناطق التنموية والمناطق الحرة","notes":[],"source":"أ- يتم استيفاء ضريبة مبيعات بنسبة (٧%) من قيمة بيع أو توريد الخدمات التي يتم تحديدها بموجب نظام وذلك عند بيعها أو توريدها للاستهلاك في المنطقة التنموية.\nب- على الرغم مما ورد في قانون ضريبة الدخل ، لا تسري النسب الضريبية المحددة في قانون ضريبة الدخل للمؤسسات المسجلة في المنطقة التنموية على الدخل المتأتي للبنوك وشركات الاتصالات الحاصلة على رخص فردية وشركات الوساطة المالية والشركات المالية، بما فيها الشركات التي تمارس أعمال الصرافة أو التمويل أو التأجير التمويلي وشركات الاستشارات والتدقيق المالي والضريبي، وشركات النقل بكافة أشكالها ونقل البضائع على الطرق وشركات التأمين وإعادة التأمين، والصناعات التعدينية والاستخراجية الأساسية، وتوليد وتوزيع الكهرباء ونقل و/أو توزيع و/أو استخراج المياه والغاز والمشتقات النفطية باستعمال خطوط الأنابيب.\nج- تستفيد المؤسسة المسجلة في المنطقة من أي اعفاءات ضريبية سارية في المملكة تتعلق بالصادرات من الخدمات إلى خارج المملكة.","title":"ضريبة المبيعات والدخل في المنطقة التنموية","memo":"⭐ ضريبة مبيعات (٧%) على بيع أو توريد الخدمات المحددة بنظام للاستهلاك في المنطقة التنموية\n⭐ لا تسري النسب الضريبية لقانون ضريبة الدخل للمؤسسات المسجلة في المنطقة التنموية على دخل: البنوك، شركات الاتصالات ذات الرخص الفردية، الوساطة والشركات المالية، التأمين، النقل، التعدين، الكهرباء والمياه والغاز بالأنابيب\n⭐ تستفيد المؤسسة المسجلة من الإعفاءات الضريبية السارية على صادرات الخدمات","qs":[{"q":"نسبة ضريبة المبيعات على بيع أو توريد الخدمات المحددة بنظام للاستهلاك في المنطقة التنموية:","o":["٧%","١٦%","الصفر","٥%"],"a":0},{"q":"وفق المادة (٢٩/ب)، أي مما يلي يعد من الجهات التي لا تسري على دخلها النسب الضريبية المحددة في قانون ضريبة الدخل للمؤسسات المسجلة في المنطقة التنموية؟","o":["شركات التأمين وإعادة التأمين","شركات الصناعات التحويلية","شركات تكنولوجيا المعلومات","الفنادق والمنشآت السياحية"],"a":0},{"q":"تستفيد المؤسسة المسجلة في المنطقة من أي إعفاءات ضريبية سارية في المملكة تتعلق بـ:","o":["الصادرات من الخدمات إلى خارج المملكة","المستوردات من السلع الاستهلاكية","رواتب الموظفين الأردنيين","أرباح بيع الأراضي"],"a":0}]},{"n":"30","chapter":"الفصل الرابع - المناطق التنموية والمناطق الحرة","notes":[],"source":"أ-١- تخضع السلع والخدمات التي تقوم المؤسسة المسجلة بشرائها أو استيرادها لغايات ممارسة نشاطها الاقتصادي داخل المنطقة التنموية للضريبة العامة على المبيعات بنسبة الصفر.\n٢- تخضع للضريبة العامة على المبيعات السلع والخدمات التي يكون منشؤها في المنطقة التنموية والتي يتم بيعها الى باقي مناطق المملكة.\n٣- تخضع مبيعات السلع الخاضعة للضريبة الخاصة عند بيعها للاستهلاك في المنطقة التنموية لضريبة المبيعات والرسوم الجمركية التي يتم استيفاؤها في المملكة.\n٤- تحدد الأحكام والاجراءات وأسس الرقابة وكيفية تحصيل ضريبة المبيعات في المنطقة التنموية المنصوص عليها في هذه المادة بمقتضى نظام.\n٥-تخضع للضريبة العامة على المبيعات والرسوم الجمركية السلع المستهلكة داخل المنطقة ما لم يكن استهلاكها قد تم لغايات ممارسة المؤسسة المسجلة لنشاطها الاقتصادي .\n٦- على الرغم مما ورد في البند (٣) من هذه الفقرة، تعفى من ضريبة المبيعات آليات المناولة والنقل المعدة لنقل عشرة اشخاص فأكثر بمن فيهم السائق والمبيعة الى المؤسسة المسجلة لغايات نقل العمال من والى منشآت عمل هذه المؤسسة في المنطقة، ويتم تنظيم اسس هذا الاعفاء وشروطه والاستهلاك بموجب نظام.\n٧- اذا تبين ان السلع او الخدمات الواردة في هذه الفقرة كلها او بعضها قد تم بيعها او التنازل عنها او التصرف فيها خلافا لأحكامها او استعملت في غير النشاط الاقتصادي او في غير الاغراض التي تم منح الاعفاء من اجلها ، فعلى المؤسسة المسجلة دفع الضرائب والرسوم والغرامات المتحققة وفق احكام التشريعات النافذة .\nب- تتمتع المؤسسة المسجلة التي تمارس نشاطا اقتصاديا في المنطقة التنموية بإعفاء المواد والمعدات والآلات والتجهيزات ومواد البناء الداخلة في بناء وإنشاء وتجهيز وتأثيث كافة انواع المشاريع التي يتم اقامتها من قبلها في المنطقة التنموية بما في ذلك قطع الغيار اللازمة لصيانتها المستمرة والبضائع المستوردة للمنطقة التنموية لممارسة النشاط الاقتصادي او المصدرة منها لخارج المملكة من الرسوم الجمركية باستثناء رسوم الصادرات وبدل الخدمات والاجور المستحقة وفقا للتشريعات النافذة.\nج-١- لا تخضع السلع المنتجة او المصنعة في المنطقة التنموية والمستوفية شروط المنشأ الاردني للرسوم الجمركية والرسوم والضرائب الاخرى عند وضعها في الاستهلاك في السوق المحلي. ٢- على الرغم مما ورد في البند (١) من هذه الفقرة، تخضع السلع المنتجة او المصنعة في المنطقة التنموية غير المستوفية شروط المنشأ الأردني وكذلك التبغ ومصنوعاته والمشروبات الكحولية والمسكرات والجعة ومنتجات المنطقة الحرة عند وضعها في الاستهلاك المحلي للرسوم الجمركية والرسوم والضرائب الاخرى المستحقة في حدود النفقات والتكاليف الاجنبية وفقا لأحكام التشريعات النافذة .\nد- تحدد شروط واجراءات تطبيق احكام هذه المادة بما في ذلك اسس احتساب قيمة ونسبة النفقات والتكاليف الاجنبية وكيفية احتساب رسومها وسدادها عند التخليص عليها لغايات وضعها للاستهلاك المحلي بمقتضى نظام.","title":"ضريبة المبيعات والرسوم الجمركية في المنطقة التنموية","memo":"⭐ مشتريات/مستوردات المؤسسة المسجلة لنشاطها داخل المنطقة التنموية: ضريبة مبيعات بنسبة الصفر\n⭐ السلع والخدمات المنشأ في المنطقة والمبيعة لباقي المملكة تخضع للضريبة العامة على المبيعات\n⭐ تعفى من ضريبة المبيعات آليات نقل (١٠) أشخاص فأكثر بمن فيهم السائق لنقل عمال المؤسسة\n⭐ سلع المنطقة المستوفية لشروط المنشأ الأردني لا تخضع للرسوم عند الاستهلاك المحلي؛ وغير المستوفية والتبغ والكحول ومنتجات المنطقة الحرة تخضع في حدود النفقات والتكاليف الأجنبية","qs":[{"q":"تخضع السلع والخدمات التي تشتريها المؤسسة المسجلة لممارسة نشاطها داخل المنطقة التنموية للضريبة العامة على المبيعات بنسبة:","o":["الصفر","٧%","١٦%","٨%"],"a":0},{"q":"تعفى من ضريبة المبيعات آليات النقل المبيعة للمؤسسة المسجلة لنقل العمال إذا كانت معدة لنقل:","o":["عشرة أشخاص فأكثر بمن فيهم السائق","عشرة أشخاص فأكثر عدا السائق","خمسة أشخاص فأكثر بمن فيهم السائق","عشرين شخصاً فأكثر"],"a":0},{"q":"سلع منتجة في المنطقة التنموية مستوفية شروط المنشأ الأردني وضعت في الاستهلاك في السوق المحلي، فإنها:","o":["لا تخضع للرسوم الجمركية والرسوم والضرائب الأخرى","تخضع للرسوم الجمركية في حدود النفقات والتكاليف الأجنبية","تخضع للرسوم الجمركية كاملة","تخضع لضريبة مبيعات بنسبة (٧%) فقط"],"a":0},{"q":"أي مما يلي يخضع للرسوم الجمركية والضرائب في حدود النفقات والتكاليف الأجنبية عند وضعه في الاستهلاك المحلي؟","o":["التبغ ومصنوعاته المنتجة في المنطقة التنموية","السلع المصنعة في المنطقة التنموية المستوفية شروط المنشأ الأردني","مواد البناء المستوردة لإنشاء مشاريع المؤسسة المسجلة","السلع المصدرة من المنطقة التنموية لخارج المملكة"],"a":0}]},{"n":"31","chapter":"الفصل الرابع - المناطق التنموية والمناطق الحرة","notes":[],"source":"تتمتع المؤسسة المسجلة التي تمارس نشاطا اقتصاديا في المنطقة الحرة بما يلي :-\nأ- الإعفاء من ضريبة الدخل عن الارباح المتأتية مما يلي:-\n١- تصدير الخدمات خارج المملكة .\n٢- تجارة الترانزيت.\n٣- البيع او التنازل عن السلع داخل حدود المنطقة الحرة .\n٤- تقديم الخدمات وتوريدها داخل المنطقة الحرة.\nب- الإعفاء من ضريبة الدخل عن رواتب وعلاوات الموظفين غير الأردنيين العاملين في المشاريع التي تقام في المنطقة الحرة.\nج- الإعفاء من الرسوم الجمركية وسائر الضرائب والرسوم المترتبة على البضائع المصدرة من المنطقة الحرة لغير السوق المحلي وعلى المواد المستوردة الداخلة في بناء وإنشاء وتجهيز وتأثيث كافة انواع المشاريع التي يتم اقامتها من قبل المؤسسة المسجلة في المنطقة الحرة بما في ذلك المعدات والآلات والتجهيزات ومواد البناء والمواد اللازمة للبنية التحتية وقطع الغيار اللازمة لصيانتها المستمرة ولا يشمل الإعفاء بدل الخدمات والرسوم المرتبطة بإجراءات حماية التجارة الدولية التي تطبقها المملكة.\nد- إعفاء الخدمات المؤداة من مؤسسة مسجلة في المنطقة الحرة من الضريبة العامة على المبيعات عند بيعها للاستهلاك في المنطقة الحرة.\nهـ- السماح للمؤسسة المسجلة بتحويل العملات الاجنبية والارباح وفق أحكام التشريعات النافذة.\nو- إخراج الآلات والمعدات والمواد والسلع والتجهيزات اللازمة لإقامة اي مشروع في المنطقة الحرة وتشغيله او توسعته والارباح الناشئة عنه الى خارج المملكة وفق احكام التشريعات النافذة.","title":"مزايا المؤسسة المسجلة في المنطقة الحرة","memo":"⭐ إعفاء من ضريبة الدخل عن أرباح: تصدير الخدمات، تجارة الترانزيت، بيع السلع داخل المنطقة الحرة، تقديم الخدمات داخلها\n⭐ إعفاء رواتب وعلاوات الموظفين غير الأردنيين من ضريبة الدخل\n⭐ إعفاء البضائع المصدرة لغير السوق المحلي ومواد إنشاء المشاريع من الرسوم والضرائب (لا يشمل بدل الخدمات ورسوم حماية التجارة الدولية)\n⭐ إعفاء الخدمات المباعة للاستهلاك في المنطقة الحرة من ضريبة المبيعات","qs":[{"q":"أي مما يلي لا تعفى أرباحه من ضريبة الدخل للمؤسسة المسجلة في المنطقة الحرة وفق المادة (٣١)؟","o":["بيع السلع إلى السوق المحلي خارج المنطقة الحرة","تجارة الترانزيت","تصدير الخدمات خارج المملكة","تقديم الخدمات وتوريدها داخل المنطقة الحرة"],"a":0},{"q":"يعفى من ضريبة الدخل في المنطقة الحرة رواتب وعلاوات:","o":["الموظفين غير الأردنيين العاملين في مشاريع المنطقة الحرة","جميع الموظفين العاملين في المنطقة الحرة","الموظفين الأردنيين فقط","أعضاء الإدارة العليا فقط"],"a":0},{"q":"لا يشمل الإعفاء من الرسوم الجمركية على المواد المستوردة لإنشاء مشاريع المؤسسة المسجلة في المنطقة الحرة:","o":["بدل الخدمات والرسوم المرتبطة بإجراءات حماية التجارة الدولية","قطع الغيار اللازمة للصيانة المستمرة","مواد البناء والمواد اللازمة للبنية التحتية","المعدات والآلات والتجهيزات"],"a":0}]},{"n":"32","chapter":"الفصل الرابع - المناطق التنموية والمناطق الحرة","notes":[],"source":"تعفى الأبنية والإنشاءات المقامة في المنطقة من عوائد التعبيد والتنظيم والتحسين ورسوم الترخيص ومن ضريبتي الأبنية والأراضي وذلك دون الإخلال بالحقوق المكتسبة.","title":"إعفاء الأبنية في المنطقة","memo":"⭐ تعفى الأبنية والإنشاءات في المنطقة من: عوائد التعبيد والتنظيم والتحسين، رسوم الترخيص، ضريبتي الأبنية والأراضي\n⭐ دون الإخلال بالحقوق المكتسبة","qs":[{"q":"تعفى الأبنية والإنشاءات المقامة في المنطقة من:","o":["ضريبتي الأبنية والأراضي","ضريبة الدخل","الضريبة العامة على المبيعات","رسوم الصادرات"],"a":0},{"q":"أي مما يلي لا يرد ضمن الإعفاءات المقررة للأبنية والإنشاءات في المنطقة وفق المادة (٣٢)؟","o":["رسوم توثيق عقود الوعد بالبيع","عوائد التعبيد والتنظيم والتحسين","رسوم الترخيص","ضريبة الأبنية والأراضي"],"a":0}]},{"n":"33","chapter":"الفصل الرابع - المناطق التنموية والمناطق الحرة","notes":[],"source":"أ- تطبق في إقليم البترا التنموي السياحي احكام المواد المتعلقة بالمزايا والحوافز داخل المناطق التنموية الواردة في هذا القانون.\nب- تخصص لسلطة إقليم البترا التنموي السياحي ما نسبته (٥٠%) من الإيرادات المتأتية للسلطة وفقاً لأحكام هذا القانون.","title":"إقليم البترا التنموي السياحي","memo":"⭐ تطبق في إقليم البترا أحكام المزايا والحوافز الخاصة بالمناطق التنموية\n⭐ تخصص لسلطة إقليم البترا (٥٠%) من الإيرادات المتأتية للسلطة وفق هذا القانون","qs":[{"q":"تطبق في إقليم البترا التنموي السياحي أحكام المزايا والحوافز الخاصة بـ:","o":["المناطق التنموية","المناطق الحرة","منطقة العقبة الاقتصادية الخاصة","المناطق الأقل نمواً"],"a":0},{"q":"النسبة المخصصة لسلطة إقليم البترا التنموي السياحي من الإيرادات المتأتية لها وفقاً لأحكام القانون:","o":["٥٠%","٢٥%","٣٠%","١٠٠%"],"a":0}]},{"n":"34","chapter":"الفصل الرابع - المناطق التنموية والمناطق الحرة","notes":[],"source":"أ- يكون لموظفي الوزارة المفوضين خطيا من الوزير لغايات قيامهم بمهامهم صفة الضابطة العدلية في حدود اختصاصهم وفق الأحكام المقررة في قانون أصول المحاكمات الجزائية، وللموظفين المفوضين الحق في ضبط اي مخالفة لأحكام هذا الفصل والانظمة الصادرة لتنفيذه والتفتيش داخل المنطقة ، ولهذه الغاية يجوز لهم الدخول إلى اي مكان وتدقيق المستندات والاطلاع على كافة الوثائق والسجلات والبيانات الالكترونية .\nب- يلتزم الموظفون المشار إليهم في الفقرة (أ) من هذه المادة عند دخولهم المؤسسة المسجلة بمراعاة أنظمتها الداخلية واجراءاتها الخاصة بالسلامة والحماية للمواد والمعاملات الحساسة.","title":"الضابطة العدلية في المنطقة","memo":"⭐ موظفو الوزارة المفوضون خطياً من الوزير لهم صفة الضابطة العدلية وفق قانون أصول المحاكمات الجزائية\n⭐ لهم ضبط المخالفات والتفتيش والدخول لأي مكان والاطلاع على الوثائق والسجلات والبيانات الإلكترونية\n⭐ يلتزمون عند دخول المؤسسة المسجلة بأنظمتها الداخلية وإجراءات السلامة","qs":[{"q":"يكتسب موظفو الوزارة صفة الضابطة العدلية في المنطقة إذا كانوا:","o":["مفوضين خطياً من الوزير","مفوضين شفهياً من أمين عام الوزارة","معينين بقرار من مجلس الوزراء","مفوضين من المطور الرئيسي"],"a":0},{"q":"تمارس صفة الضابطة العدلية لموظفي الوزارة المفوضين وفق الأحكام المقررة في:","o":["قانون أصول المحاكمات الجزائية","قانون أصول المحاكمات المدنية","قانون العقوبات","قانون الجمارك"],"a":0},{"q":"عند دخول الموظفين المفوضين إلى المؤسسة المسجلة يلتزمون بـ:","o":["مراعاة أنظمتها الداخلية وإجراءاتها الخاصة بالسلامة والحماية للمواد والمعاملات الحساسة","الحصول على إذن مسبق من المحكمة","الحصول على موافقة المطور الرئيسي","إخطار المؤسسة قبل (١٥) يوم عمل"],"a":0}]},{"n":"35","chapter":"الفصل الخامس - تسجيل الأنشطة الاقتصادية وترخيصها","notes":[],"source":"أ- يتم تسجيل الشركات والمؤسسات الفردية وفق أحكام التشريعات ذات العلاقة.\nب-لا يشترط لتسجيل أي شركة أو مؤسسة فردية الحصول على موافقة مسبقة من أي جهة أخرى ما لم ينص أي تشريع على غير ذلك .","title":"تسجيل الشركات والمؤسسات الفردية","memo":"⭐ تسجل الشركات والمؤسسات الفردية وفق التشريعات ذات العلاقة\n⭐ لا يشترط الحصول على موافقة مسبقة من أي جهة أخرى ما لم ينص تشريع على غير ذلك","qs":[{"q":"لتسجيل شركة أو مؤسسة فردية وفق قانون البيئة الاستثمارية:","o":["لا يشترط الحصول على موافقة مسبقة من أي جهة أخرى ما لم ينص أي تشريع على غير ذلك","يشترط الحصول على موافقة مسبقة من وزارة الاستثمار","يشترط الحصول على موافقة مجلس الاستثمار","يشترط الحصول على بطاقة تعريف مستثمر"],"a":0},{"q":"يتم تسجيل الشركات والمؤسسات الفردية وفق:","o":["أحكام التشريعات ذات العلاقة","أحكام قانون البيئة الاستثمارية حصراً","تعليمات يصدرها وزير الاستثمار","اتفاقية التطوير"],"a":0}]},{"n":"36","chapter":"الفصل الخامس - تسجيل الأنشطة الاقتصادية وترخيصها","notes":[],"source":"ينشأ سجل عام للأنشطة الاقتصادية المسجلة والمرخصة في المملكة تنظم أحكامه بمقتضى نظام على أن تحدد بمقتضاه الجهة التي تتولى الاشراف على هذا السجل.","title":"السجل العام للأنشطة الاقتصادية","memo":"⭐ ينشأ سجل عام للأنشطة الاقتصادية المسجلة والمرخصة في المملكة\n⭐ تنظم أحكامه والجهة المشرفة عليه بمقتضى نظام","qs":[{"q":"تحدد الجهة التي تتولى الإشراف على السجل العام للأنشطة الاقتصادية بمقتضى:","o":["نظام","قرار من الوزير","قرار من مجلس الاستثمار","تعليمات"],"a":0},{"q":"يشمل السجل العام المنصوص عليه في المادة (٣٦):","o":["الأنشطة الاقتصادية المسجلة والمرخصة في المملكة","المستثمرين غير الأردنيين فقط","المؤسسات المسجلة في المناطق الحرة فقط","صناديق الاستثمار المشترك فقط"],"a":0}]},{"n":"37","chapter":"الفصل الخامس - تسجيل الأنشطة الاقتصادية وترخيصها","notes":[],"source":"أ-على الرغم مما ورد في أي تشريع آخر، تقوم الوزارة بتقديم الخدمة الاستثمارية الشاملة لترخيص الأنشطة الاقتصادية، من خلال منصة الكترونية مشتركة مع الجهات المسؤولة عن التسجيل والترخيص ولا يمنع ذلك تقديم الطلب وجاهياً في الوزارة.\nب- على الجهات الرسمية ذات العلاقة انجاز المعاملات المرتبطة بالخدمة الاستثمارية الشاملة خلال مدة لا تتجاوز (١٥) يوم عمل من تاريخ تسلم الطلب المستكمل للمتطلبات، وفي حال تأخر الجهة الرسمية عن الرد قبل انتهاء هذه الفترة يعتبر ذلك موافقة تلقائية لإنجاز المعاملة.\nج- يحظر على الجهة الرسمية الطلب من المستثمر تقديم أي وثيقة سارية المفعول صادرة عن جهة رسمية أخرى في حال توفر الربط الالكتروني بين هاتين الجهتين.\nد- على الجهات الرسمية ذات العلاقة تسمية مفوض أو أكثر لمتابعة وتسهيل معاملات المستثمر خلال مدة لا تتجاوز عشرة أيام عمل من تاريخ تسلمها كتاباً من الوزارة بذلك.\nهــ- على الرغم مما ورد في أي تشريع آخر، يكون للمفوض المشار إليه في الفقرة (د) من هذه المادة صلاحية إصدار الموافقات المطلوبة وفقاً للتشريعات التي تطبقها الجهة الرسمية التي يمثلها.\nو- ينظم عمل الخدمة الاستثمارية الشاملة للوزارة والأنشطة الاقتصادية المشمولة بخدماتها والشروط والمؤهلات الواجب توافرها في مفوضي الجهات الرسمية وسائر الأمور المتعلقة بهم بما في ذلك العقوبات التأديبية في حال إخلالهم بمسؤولياتهم بمقتضى نظام.","title":"الخدمة الاستثمارية الشاملة","memo":"⭐ تقدمها الوزارة عبر منصة إلكترونية مشتركة، ولا يمنع ذلك تقديم الطلب وجاهياً\n⭐ على الجهات الرسمية إنجاز المعاملات خلال (١٥) يوم عمل من تسلم الطلب المستكمل، والتأخر يعتبر موافقة تلقائية\n⭐ يحظر طلب وثيقة سارية صادرة عن جهة أخرى عند توفر الربط الإلكتروني\n⭐ تسمية مفوض أو أكثر خلال (١٠) أيام عمل من تسلم كتاب الوزارة، وله صلاحية إصدار الموافقات","qs":[{"q":"المدة القصوى لإنجاز الجهات الرسمية المعاملات المرتبطة بالخدمة الاستثمارية الشاملة:","o":["١٥ يوم عمل من تاريخ تسلم الطلب المستكمل للمتطلبات","٢٠ يوم عمل من تاريخ تسلم الطلب","١٠ أيام عمل من تاريخ تسلم الطلب المستكمل","٣٠ يوماً من تاريخ تقديم الطلب"],"a":0},{"q":"إذا تأخرت الجهة الرسمية عن الرد على معاملة مستكملة ضمن الخدمة الاستثمارية الشاملة حتى انتهاء المدة المحددة، فإن ذلك يعتبر:","o":["موافقة تلقائية لإنجاز المعاملة","رفضاً ضمنياً للمعاملة","سبباً للتظلم أمام لجنة التظلمات فقط","تمديداً تلقائياً للمدة"],"a":0},{"q":"على الجهات الرسمية تسمية مفوض لمتابعة معاملات المستثمر خلال مدة لا تتجاوز:","o":["عشرة أيام عمل من تاريخ تسلمها كتاب الوزارة","خمسة عشر يوم عمل من تاريخ تسلمها كتاب الوزارة","ثلاثة أشهر من تاريخ نفاذ القانون","عشرين يوم عمل من تاريخ تسلمها كتاب الوزارة"],"a":0},{"q":"طلبت جهة رسمية من مستثمر تقديم وثيقة سارية صادرة عن جهة رسمية أخرى يتوفر بينهما ربط إلكتروني، فإن هذا الطلب:","o":["محظور","جائز بشرط موافقة الوزارة","جائز إذا كانت الوثيقة صادرة قبل سنة","جائز دائماً"],"a":0}]},{"n":"38","chapter":"الفصل الخامس - تسجيل الأنشطة الاقتصادية وترخيصها","notes":[],"source":"لا يجوز لأي جهة رسمية فرض متطلبات للحصول على الرخصة ما لم تكن مخولة بذلك صراحة بموجب التشريعات النافذة.","title":"حظر فرض متطلبات غير مخولة","memo":"⭐ لا يجوز لأي جهة رسمية فرض متطلبات للحصول على الرخصة ما لم تكن مخولة بذلك صراحة بموجب التشريعات النافذة","qs":[{"q":"يجوز للجهة الرسمية فرض متطلبات للحصول على الرخصة:","o":["إذا كانت مخولة بذلك صراحة بموجب التشريعات النافذة","متى رأت ذلك مناسباً لحماية المصلحة العامة","بموافقة المستثمر","بقرار داخلي من رئيس الجهة"],"a":0}]},{"n":"39","chapter":"الفصل الخامس - تسجيل الأنشطة الاقتصادية وترخيصها","notes":[],"source":"يجب أن لا يؤدي القرار الصادر بمنح الرخصة أو رفضها إلى أي مما يلي:-\nأ - تقييد المنافسة.\nب- دعم أو حماية احتكار أو وضع مهيمن لشخص أو أكثر.\nج- تقييد حرية النشاط الاقتصادي.","title":"ضوابط قرار منح الرخصة أو رفضها","memo":"⭐ يجب ألا يؤدي قرار منح الرخصة أو رفضها إلى: تقييد المنافسة، أو دعم أو حماية احتكار أو وضع مهيمن، أو تقييد حرية النشاط الاقتصادي","qs":[{"q":"أي مما يلي لا يعد من الآثار المحظورة لقرار منح الرخصة أو رفضها وفق المادة (٣٩)؟","o":["تحقيق الرقابة اللاحقة على النشاط","تقييد المنافسة","دعم أو حماية احتكار أو وضع مهيمن لشخص أو أكثر","تقييد حرية النشاط الاقتصادي"],"a":0},{"q":"يجب ألا يؤدي القرار الصادر بمنح الرخصة أو رفضها إلى:","o":["دعم أو حماية وضع مهيمن لشخص أو أكثر","تعزيز المنافسة","حماية المستهلك","تسهيل ممارسة النشاط الاقتصادي"],"a":0}]},{"n":"40","chapter":"الفصل الخامس - تسجيل الأنشطة الاقتصادية وترخيصها","notes":[],"source":"مع مراعاة المادة (٤٣) من هذا القانون، تلتزم الجهة الرسمية بما يلي :-\nأ- تحديد كافة متطلبات الرخصة ونشرها بشكل واضح يسهل الاطلاع عليها وتزويد الوزارة بنسخة عنها ولا يجوز فرض متطلبات أخرى خلافا لأحكام هذا القانون.\nب- تصنيف الرخص وتحديد متطلباتها وشروط كل منها بما فيها الرخص التي تمنح عند تقديم الطلب ويتم التدقيق عليها لاحقاً من الجهة الرسمية.\nج- تحديد المدة اللازمة لمنح الرخصة وإجراءاتها وفي حال عدم تحديد المدة يجب أن لا تزيد مدة منح الرخصة على (١٥) يوم عمل من تاريخ استكمال المتطلبات القانونية لمنح الرخصة.\nد- اتخاذ قرارها بمنح الرخصة أو رفضها خلال المدة المحددة على أن يكون قرارها بالرفض مسببا.\nهـ- تحديد مدة سريان الرخصة وفقا لتشريعاتها ويجوز أن تكون مدة سريانها سنة أو أكثر بناء على طلب صاحب العلاقة مع مراعاة استيفاء الرسوم المفروضة على ذلك.","title":"التزامات الجهة الرسمية في الترخيص","memo":"⭐ تحديد ونشر كافة متطلبات الرخصة وتزويد الوزارة بنسخة عنها\n⭐ إذا لم تحدد مدة منح الرخصة: لا تزيد على (١٥) يوم عمل من استكمال المتطلبات القانونية\n⭐ قرار الرفض يجب أن يكون مسبباً\n⭐ يجوز أن تكون مدة سريان الرخصة سنة أو أكثر بناء على طلب صاحب العلاقة مع استيفاء الرسوم","qs":[{"q":"في حال عدم تحديد الجهة الرسمية لمدة منح الرخصة، يجب ألا تزيد المدة على:","o":["١٥ يوم عمل من تاريخ استكمال المتطلبات القانونية","٢٠ يوم عمل من تاريخ تقديم الطلب","١٠ أيام عمل من تاريخ تقديم الطلب","ثلاثين يوماً من تاريخ استكمال المتطلبات"],"a":0},{"q":"يشترط في قرار الجهة الرسمية برفض منح الرخصة أن يكون:","o":["مسبباً","صادراً عن مجلس الوزراء","مصادقاً عليه من الوزارة","منشوراً في الجريدة الرسمية"],"a":0},{"q":"يجوز أن تكون مدة سريان الرخصة سنة أو أكثر:","o":["بناء على طلب صاحب العلاقة مع مراعاة استيفاء الرسوم المفروضة","بقرار من الوزارة دون طلب","للمستثمرين غير الأردنيين فقط","بشرط تشغيل (٢٥٠) أردنياً على الأقل"],"a":0}]},{"n":"41","chapter":"الفصل الخامس - تسجيل الأنشطة الاقتصادية وترخيصها","notes":[],"source":"على الجهة الرسمية قبل إلغاء أي رخصة أو سحبها أو تعليقها مراعاة ما يلي:-\nأ- إخطار صاحب الرخصة خطيا بمخالفة أحكام الرخصة.\nب- منح صاحب الرخصة مهلة لتصويب المخالفة أو تقديم ما يثبت عدم ارتكابه لها.\nج- إخطار الوزارة في حال كانت الرخصة تتعلق بالأنشطة الاقتصادية المشمولة بالخدمة الاستثمارية الشاملة.","title":"إجراءات إلغاء الرخصة أو سحبها أو تعليقها","memo":"⭐ قبل الإلغاء أو السحب أو التعليق: إخطار صاحب الرخصة خطياً بالمخالفة\n⭐ منحه مهلة لتصويب المخالفة أو إثبات عدم ارتكابها\n⭐ إخطار الوزارة إذا كانت الرخصة متعلقة بأنشطة مشمولة بالخدمة الاستثمارية الشاملة","qs":[{"q":"قبل قيام الجهة الرسمية بإلغاء رخصة أو سحبها أو تعليقها يجب عليها أولاً:","o":["إخطار صاحب الرخصة خطياً بمخالفة أحكام الرخصة","الحصول على حكم قضائي","الحصول على موافقة مجلس الوزراء","فرض غرامة على صاحب الرخصة"],"a":0},{"q":"تلتزم الجهة الرسمية بإخطار الوزارة قبل إلغاء الرخصة في حال كانت الرخصة:","o":["تتعلق بالأنشطة الاقتصادية المشمولة بالخدمة الاستثمارية الشاملة","صادرة لمستثمر غير أردني","صادرة منذ أكثر من سنة","تتعلق بنشاط في المناطق الأقل نمواً"],"a":0}]},{"n":"42","chapter":"الفصل الخامس - تسجيل الأنشطة الاقتصادية وترخيصها","notes":[],"source":"أ- تقوم الوزارة وخلال ثلاثة أشهر من تاريخ نفاذ هذا القانون بإعداد دليل للترخيص يتضمن الشروط والإجراءات والمتطلبات والمدد القانونية لإصدار الرخصة وفقاً للتشريعات النافذة التي تطبقها الجهات الرسمية وذلك وفقاً للنموذج المعتمد في الوزارة لهذه الغاية على ان ينشر على موقع الوزارة الإلكتروني ، وعلى الجهات الرسمية تزويد الوزارة بالبيانات التي تطلبها واللازمة لإعداد دليل الترخيص خلال (١٥) يوم عمل من تاريخ تسلمها طلباً بذلك من الوزارة.\nب- تقوم الوزارة بعرض مسودة دليل الترخيص على الجهات الرسمية للاطلاع عليها وإبداء ملاحظاتها، وفي حال لم تزود أي جهة رسمية الوزارة بملاحظاتها خلال (٢٠) يوم عمل من تاريخ تسلمها مسودة الدليل المذكور يعد ذلك موافقة منها على ما ورد فيه.\nج-تقوم الوزارة وبشكل سنوي أو كلما دعت الحاجة بمراجعة دليل الترخيص وتحديث بياناته في ضوء التعديلات التي تطرأ على التشريعات النافذة على أن تتبع في أي تحديث أو تعديل على دليل الترخيص الإجراءات نفسها الواردة في هذه المادة لاعتماده.","title":"دليل الترخيص","memo":"⭐ تعده الوزارة خلال (٣) أشهر من نفاذ القانون وينشر على موقعها الإلكتروني\n⭐ تزود الجهات الرسمية الوزارة بالبيانات خلال (١٥) يوم عمل من تسلم الطلب\n⭐ عدم إبداء الملاحظات على المسودة خلال (٢٠) يوم عمل يعد موافقة\n⭐ يراجع سنوياً أو كلما دعت الحاجة بالإجراءات نفسها","qs":[{"q":"تقوم الوزارة بإعداد دليل الترخيص خلال:","o":["ثلاثة أشهر من تاريخ نفاذ القانون","ستة أشهر من تاريخ نفاذ القانون","سنة من تاريخ نفاذ القانون","تسعين يوماً من تاريخ نشر القانون"],"a":0},{"q":"إذا لم تزود الجهة الرسمية الوزارة بملاحظاتها على مسودة دليل الترخيص خلال (٢٠) يوم عمل من تسلمها، فإن ذلك يعد:","o":["موافقة منها على ما ورد فيه","رفضاً للمسودة","سبباً لرفع الأمر إلى مجلس الاستثمار","تمديداً للمدة (١٠) أيام أخرى"],"a":0},{"q":"مدة تزويد الجهات الرسمية الوزارة بالبيانات اللازمة لإعداد دليل الترخيص:","o":["١٥ يوم عمل من تاريخ تسلمها الطلب","٢٠ يوم عمل من تاريخ تسلمها الطلب","١٠ أيام عمل من تاريخ تسلمها الطلب","ثلاثة أشهر من تاريخ نفاذ القانون"],"a":0}]},{"n":"43","chapter":"الفصل الخامس - تسجيل الأنشطة الاقتصادية وترخيصها","notes":[],"source":"على الجهات الرسمية التي تمنح الرخص مراعاة أحكام هذا الفصل في كل ما يتعلق بمنح الرخص من متطلبات وشروط وإجراءات و مواءمة تشريعاتها بما يتفق وأحكامه خلال مدة ستة أشهر من تاريخ نفاذ أحكام هذا القانون.","title":"مواءمة تشريعات الجهات المانحة للرخص","memo":"⭐ على الجهات الرسمية مراعاة أحكام فصل التسجيل والترخيص\n⭐ ومواءمة تشريعاتها خلال (٦) أشهر من تاريخ نفاذ القانون","qs":[{"q":"مدة مواءمة الجهات الرسمية المانحة للرخص لتشريعاتها مع أحكام فصل التسجيل والترخيص:","o":["ستة أشهر من تاريخ نفاذ أحكام القانون","ثلاثة أشهر من تاريخ نفاذ أحكام القانون","سنة من تاريخ نفاذ أحكام القانون","سبع سنوات من تاريخ نفاذ أحكام القانون"],"a":0},{"q":"تلتزم الجهات الرسمية التي تمنح الرخص بموجب المادة (٤٣) بـ:","o":["مواءمة تشريعاتها بما يتفق وأحكام فصل تسجيل الأنشطة الاقتصادية وترخيصها","إلغاء جميع رسوم الترخيص","نقل صلاحيات الترخيص إلى الوزارة","الحصول على موافقة مجلس الاستثمار على كل رخصة"],"a":0}]},{"n":"44","chapter":"أحكام ختامية","notes":[],"source":"أ- تشكل في الوزارة بقرار من الوزير لجنة أو اكثر للتظلمات برئاسة أمين عام الوزارة.\nب- تتولى اللجنة النظر في طلبات التظلم المقدمة من المستثمرين للتحقق من سلامة الإجراءات المتخذة أو القرارات الصادرة عن الجهة الرسمية.\nج- تنظم الأمور المتعلقة بعمل اللجنة وعدد أعضائها والنصاب القانوني لاجتماعاتها واتخاذ قراراتها والمدد الزمنية اللازمة وسائر الأحكام والإجراءات المتعلقة بالتظلم بمقتضى نظام.\nد- في حال عدم امتثال الجهة الرسمية لتوصية اللجنة يرفع الوزير التوصية الى المجلس.","title":"لجنة التظلمات","memo":"⭐ تشكل في الوزارة بقرار من الوزير لجنة أو أكثر للتظلمات برئاسة أمين عام الوزارة\n⭐ تنظر في تظلمات المستثمرين للتحقق من سلامة إجراءات وقرارات الجهة الرسمية\n⭐ عدد أعضائها ونصابها ومددها بمقتضى نظام\n⭐ عند عدم امتثال الجهة الرسمية لتوصية اللجنة يرفع الوزير التوصية إلى المجلس","qs":[{"q":"يرأس لجنة التظلمات:","o":["أمين عام الوزارة","الوزير","رئيس الوزراء","أحد ممثلي القطاع الخاص"],"a":0},{"q":"تشكل لجنة التظلمات بقرار من:","o":["الوزير","مجلس الوزراء","مجلس الاستثمار","رئيس الوزراء"],"a":0},{"q":"في حال عدم امتثال الجهة الرسمية لتوصية لجنة التظلمات:","o":["يرفع الوزير التوصية إلى مجلس الاستثمار","تحال التوصية إلى المحكمة الإدارية مباشرة","تصبح التوصية ملزمة حكماً","يرفع أمين عام الوزارة التوصية إلى مجلس الوزراء"],"a":0}]},{"n":"45","chapter":"الفصل الخامس - تسجيل الأنشطة الاقتصادية وترخيصها","notes":[],"source":"أ- يجوز تسوية منازعات عقود الاستثمار بين الجهة الرسمية والمستثمر من خلال التحكيم وفقا للقواعد المتفق عليها بينهما وفي حال وجود اتفاق تحكيم دون تحديد القواعد فللمستثمر اختيار تطبيق أي من القواعد التالية:-\n١- قانون التحكيم الأردني.\n٢- قواعد التحكيم الخاصة بلجنة الأمم المتحدة للقانون التجاري الدولي (الأونسيترال).\n٣- قواعد التحكيم الخاصة بغرفة التجارة الدولية.\nب- يكون مكان التحكيم في المملكة في مدينة عمان ما لم ينص العقد على غير ذلك.\nج- إذا صدر قرار تحكيم من هيئة تحكيم أجنبية أو دولية بمقتضى أحكام هذه المادة يتم تنفيذه وفقا لقانون تنفيذ الأحكام الأجنبية والاتفاقيات ذات العلاقة النافذة في المملكة","title":"التحكيم في منازعات عقود الاستثمار","memo":"⭐ يجوز تسوية منازعات عقود الاستثمار بين الجهة الرسمية والمستثمر بالتحكيم وفق القواعد المتفق عليها\n⭐ عند وجود اتفاق تحكيم دون تحديد القواعد يختار المستثمر: قانون التحكيم الأردني، أو قواعد الأونسيترال، أو قواعد غرفة التجارة الدولية\n⭐ مكان التحكيم: مدينة عمان ما لم ينص العقد على غير ذلك\n⭐ قرار التحكيم الأجنبي ينفذ وفق قانون تنفيذ الأحكام الأجنبية","qs":[{"q":"في حال وجود اتفاق تحكيم دون تحديد القواعد، فإن اختيار قواعد التحكيم يكون لـ:","o":["المستثمر","الجهة الرسمية","هيئة التحكيم","وزير الاستثمار"],"a":0},{"q":"أي مما يلي ليس من قواعد التحكيم التي يحق للمستثمر اختيارها عند عدم تحديد القواعد؟","o":["قواعد مركز تحكيم دولة المستثمر","قانون التحكيم الأردني","قواعد الأونسيترال","قواعد غرفة التجارة الدولية"],"a":0},{"q":"مكان التحكيم في منازعات عقود الاستثمار ما لم ينص العقد على غير ذلك:","o":["مدينة عمان","مدينة العقبة","مقر غرفة التجارة الدولية","مدينة يختارها المستثمر"],"a":0}]},{"n":"46","chapter":"الفصل الخامس - تسجيل الأنشطة الاقتصادية وترخيصها","notes":[],"source":"تطبق المحكمة أو هيئة التحكيم على منازعات عقود الاستثمار القانون المتفق عليه بين الأطراف وفي حال عدم وجود مثل هذا الاتفاق تطُبق القانون الأردني باستثناء قواعد القانون الدولي الخاص.","title":"القانون الواجب التطبيق على منازعات الاستثمار","memo":"⭐ تطبق المحكمة أو هيئة التحكيم القانون المتفق عليه بين الأطراف\n⭐ عند عدم الاتفاق يطبق القانون الأردني باستثناء قواعد القانون الدولي الخاص","qs":[{"q":"عند عدم اتفاق الأطراف على القانون الواجب التطبيق على منازعات عقود الاستثمار، تطبق المحكمة أو هيئة التحكيم:","o":["القانون الأردني باستثناء قواعد القانون الدولي الخاص","القانون الأردني بما فيه قواعد القانون الدولي الخاص","قانون دولة المستثمر","قواعد الأونسيترال"],"a":0},{"q":"القانون الذي يطبق أولاً على منازعات عقود الاستثمار:","o":["القانون المتفق عليه بين الأطراف","القانون الأردني حصراً","القانون الذي تختاره الجهة الرسمية","قانون مكان تنفيذ العقد"],"a":0}]},{"n":"47","chapter":"الفصل الخامس - تسجيل الأنشطة الاقتصادية وترخيصها","notes":[],"source":"أ- يتم إنشاء المراكز التجارية وإقامة المعارض وفتح الاسواق داخل المملكة وخارجها وتنظيم البعثات التجارية لترويج المنتوجات الوطنية وتسويقها من قبل وزارة الصناعة والتجارة والتموين.\nب- تتم الموافقة على طلبات المؤسسات الخاصة والعامة المحلية والأجنبية لإقامة المعارض التجارية والصناعية في المملكة ومراقبتها من قبل وزارة الصناعة والتجارة والتموين ، ويتم تنظيم المعارض للمنتجات الأردنية في الخارج أو المشاركة في معارض مقامة خارج المملكة وفقا لشروط يحددها وزير الصناعة والتجارة والتموين بمقتضى تعليمات تنشر في الجريدة الرسمية.\nج- لوزير الصناعة والتجارة والتموين ان يعهد بصلاحيات وزارة الصناعة والتجارة والتموين المنصوص عليها في الفقرتين (أ) و (ب) من هذه المادة الى أي جهة .","title":"المعارض والمراكز التجارية","memo":"⭐ إنشاء المراكز التجارية وإقامة المعارض وتنظيم البعثات التجارية: وزارة الصناعة والتجارة والتموين\n⭐ شروط تنظيم المعارض في الخارج يحددها وزير الصناعة والتجارة بتعليمات تنشر في الجريدة الرسمية\n⭐ لوزير الصناعة والتجارة أن يعهد بهذه الصلاحيات إلى أي جهة","qs":[{"q":"الجهة المختصة بالموافقة على طلبات إقامة المعارض التجارية والصناعية في المملكة ومراقبتها:","o":["وزارة الصناعة والتجارة والتموين","وزارة الاستثمار","مجلس الاستثمار","غرفة تجارة الأردن"],"a":0},{"q":"تحدد شروط تنظيم المعارض للمنتجات الأردنية في الخارج بمقتضى:","o":["تعليمات يصدرها وزير الصناعة والتجارة والتموين تنشر في الجريدة الرسمية","نظام يصدره مجلس الوزراء","تعليمات يصدرها وزير الاستثمار","قرار من مجلس الاستثمار"],"a":0},{"q":"لوزير الصناعة والتجارة والتموين أن يعهد بصلاحيات وزارته المتعلقة بالمعارض والمراكز التجارية إلى:","o":["أي جهة","وزارة الاستثمار حصراً","الغرف التجارية حصراً","أمين عام وزارته حصراً"],"a":0}]},{"n":"48","chapter":"الفصل الخامس - تسجيل الأنشطة الاقتصادية وترخيصها","notes":[],"source":"للوزير تفويض أي من صلاحياته المنصوص عليها في هذا القانون لأمين عام الوزارة أو لأي من كبار موظفيها على ان يكون التفويض خطيا ومحددا.","title":"تفويض صلاحيات الوزير","memo":"⭐ للوزير تفويض أي من صلاحياته لأمين عام الوزارة أو لأي من كبار موظفيها\n⭐ يجب أن يكون التفويض خطياً ومحدداً","qs":[{"q":"يشترط في تفويض الوزير لصلاحياته المنصوص عليها في القانون أن يكون:","o":["خطياً ومحدداً","خطياً وعاماً","بموافقة مجلس الوزراء","منشوراً في الجريدة الرسمية"],"a":0},{"q":"يجوز للوزير تفويض أي من صلاحياته إلى:","o":["أمين عام الوزارة أو أي من كبار موظفيها","المطور الرئيسي","أي موظف في الجهات الرسمية الأخرى","رئيس لجنة الحوافز والإعفاءات"],"a":0}]},{"n":"49","chapter":"الفصل الخامس - تسجيل الأنشطة الاقتصادية وترخيصها","notes":[],"source":"مع مراعاة المادة (٥٠) من هذا القانون، لا يعمل بأي نص ورد في أي تشريع آخر الى المدى الذي يتعارض فيه مع احكام هذا القانون.","title":"أولوية أحكام القانون","memo":"⭐ مع مراعاة المادة (٥٠): لا يعمل بأي نص في تشريع آخر إلى المدى الذي يتعارض فيه مع أحكام هذا القانون","qs":[{"q":"إذا تعارض نص في تشريع آخر مع أحكام قانون البيئة الاستثمارية (مع مراعاة المادة ٥٠)، فإن:","o":["لا يعمل بذلك النص إلى المدى الذي يتعارض فيه مع أحكام هذا القانون","يطبق التشريع الآخر لأنه خاص","يعرض الأمر على مجلس الاستثمار للبت فيه","يطبق التشريع الأحدث صدوراً"],"a":0},{"q":"قاعدة عدم العمل بالنصوص المتعارضة مع قانون البيئة الاستثمارية مقيدة بمراعاة المادة (٥٠) المتعلقة بـ:","o":["عدم سريان القانون على منطقة العقبة الاقتصادية الخاصة","إصدار الأنظمة والتعليمات التنفيذية","إلغاء قانون الاستثمار لسنة ٢٠١٤","تفويض صلاحيات الوزير"],"a":0}]},{"n":"50","chapter":"الفصل الخامس - تسجيل الأنشطة الاقتصادية وترخيصها","notes":[],"source":"لا تسري أحكام هذا القانون على منطقة العقبة الاقتصادية الخاصة.","title":"استثناء منطقة العقبة الاقتصادية الخاصة","memo":"⭐ لا تسري أحكام هذا القانون على منطقة العقبة الاقتصادية الخاصة","qs":[{"q":"لا تسري أحكام قانون البيئة الاستثمارية على:","o":["منطقة العقبة الاقتصادية الخاصة","إقليم البترا التنموي السياحي","المناطق الحرة","المناطق الأقل نمواً"],"a":0}]},{"n":"51","chapter":"الفصل الخامس - تسجيل الأنشطة الاقتصادية وترخيصها","notes":[],"source":"أ- يصدر مجلس الوزراء الأنظمة اللازمة لتنفيذ أحكام هذا القانون.\nب- يصدر الوزير التعليمات اللازمة لتنفيذ أحكام هذا القانون.","title":"الأنظمة والتعليمات التنفيذية","memo":"⭐ يصدر مجلس الوزراء الأنظمة اللازمة لتنفيذ القانون\n⭐ يصدر الوزير التعليمات اللازمة لتنفيذ القانون","qs":[{"q":"الجهة المختصة بإصدار التعليمات اللازمة لتنفيذ أحكام قانون البيئة الاستثمارية:","o":["الوزير","مجلس الوزراء","مجلس الاستثمار","أمين عام الوزارة"],"a":0}]},{"n":"52","chapter":"الفصل الخامس - تسجيل الأنشطة الاقتصادية وترخيصها","notes":[],"source":"أ-عند نفاذ أحكام هذا القانون يلغى قانون الاستثمار رقم (٣٠) لسنة ٢٠١٤.\nب-على الرغم مما ورد في الفقرة (أ) من هذه المادة، يستمر العمل بالأنظمة والتعليمات والقرارات الصادرة بمقتضى قانون الاستثمار إلى ان تلغى او تعدل او يستبدل غيرها بها وفقا لأحكام هذا القانون.","title":"إلغاء قانون الاستثمار لسنة ٢٠١٤","memo":"⭐ يلغى قانون الاستثمار رقم (٣٠) لسنة ٢٠١٤ عند نفاذ هذا القانون\n⭐ يستمر العمل بالأنظمة والتعليمات والقرارات الصادرة بمقتضاه إلى أن تلغى أو تعدل أو يستبدل غيرها بها","qs":[{"q":"القانون الذي ألغي بنفاذ قانون البيئة الاستثمارية لسنة ٢٠٢٢:","o":["قانون الاستثمار رقم (٣٠) لسنة ٢٠١٤","قانون تشجيع الاستثمار لسنة ١٩٩٥","قانون المناطق التنموية والحرة لسنة ٢٠٠٨","قانون منطقة العقبة الاقتصادية الخاصة"],"a":0},{"q":"الأنظمة والتعليمات الصادرة بمقتضى قانون الاستثمار لسنة ٢٠١٤:","o":["يستمر العمل بها إلى أن تلغى أو تعدل أو يستبدل غيرها بها","تلغى حكماً بنفاذ القانون الجديد","يستمر العمل بها لمدة سنة واحدة فقط","يستمر العمل بها لمدة سبع سنوات"],"a":0}]},{"n":"53","chapter":"الفصل الخامس - تسجيل الأنشطة الاقتصادية وترخيصها","notes":[],"source":"رئيس الوزراء والوزراء مكلفون بتنفيذ أحكام هذا القانون.","title":"تنفيذ القانون","memo":"⭐ رئيس الوزراء والوزراء مكلفون بتنفيذ أحكام هذا القانون.","qs":[{"q":"المكلفون بتنفيذ أحكام قانون البيئة الاستثمارية:","o":["رئيس الوزراء والوزراء","وزير الاستثمار وحده","مجلس الاستثمار","وزير الاستثمار ووزير المالية"],"a":0}]}]};
